import {boardSVG,mountBoard,openBoard,closeBoards} from './domartavla.js';
import {emptyBoard} from './board-data.js';
import {publicFaq} from './faq.js';
import {statutesParagraphs} from './statutes.js';
import {developmentSteps} from './development.js';
