const main = document.querySelector('#main');
const config = window.VDK_CONFIG || {};
const apiBase = (config.apiBase || '').replace(/\/$/, '');
let user = null;
let settings = null;
let pageEpoch = 0;
let messageUnread=0;
const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = v => new Intl.DateTimeFormat('sv-SE', { dateStyle: 'medium' }).format(new Date(v));
const time = v => `${Math.floor(v / 60).toString().padStart(2,'0')}:${Math.floor(v % 60).toString().padStart(2,'0')}`;
const icons = {
  people: '<circle cx="16" cy="14" r="6"/><circle cx="34" cy="16" r="5"/><path d="M4 42v-7c0-8 24-8 24 0v7ZM31 28c10-2 14 3 14 8v6H33"/>',
  growth: '<path d="M5 43V28h9v15ZM20 43V18h9v25ZM35 43V5h9v38"/><path d="m5 20 12-9 9 2L40 2"/>',
  shield: '<path d="M24 3 43 10v13c0 12-10 20-19 25C15 43 5 35 5 23V10Z"/><path d="m14 24 7 7 14-16"/>',
  whistle: '<circle cx="17" cy="31" r="13"/><circle cx="17" cy="31" r="5"/><path d="m26 21 15-9 5 10-17 11M8 8l4 7M23 3v9M36 4l-6 9"/>'
};
function icon(name){return `<svg class="pillar-icon" viewBox="0 0 50 52" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;}
function page(title, intro, body, eyebrow = 'Värmlands Domarkollektiv') {
  return `<section class="page container"><div class="page-head"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${intro ? `<p class="lead">${intro}</p>` : ''}</div>${body}</section>`;
}
function notice(text, type=''){return `<div class="notice ${type}" role="${type==='error'?'alert':'status'}">${text}</div>`;}
function empty(title, body){return `<div class="empty-state"><h3>${title}</h3><p>${body}</p></div>`;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;setTimeout(()=>{el.hidden=true},5000);}
async function api(path, { method='GET', body } = {}) {
  let response;
  try {response=await fetch(`${apiBase}/api${path}`, {method,credentials:'include',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});}
  catch {throw new Error('Medlemstjänsten går inte att nå just nu. Försök igen senare.');}
  const type=response.headers.get('content-type')||'';
  if(!type.includes('application/json')) throw new Error('Medlemstjänsten är tillfälligt otillgänglig. Din ansökan har inte skickats. Försök igen senare.');
  const data=await response.json();
  if(!response.ok) throw new Error(data.error||'Något gick fel. Försök igen.');
  return data;
}
async function loadSettings(){if(settings)return settings;try{settings=await api('/settings');}catch{settings={season:'2026/27',fee:100,applicationsOpen:false};}return settings;}
function formError(form, error){let el=form.querySelector('[data-error]');if(el){el.textContent=error.message;el.setAttribute('tabindex','-1');el.focus();}}
async function submit(form, action){const button=form.querySelector('button[type="submit"]');if(button.disabled)return;const label=button.textContent;button.disabled=true;button.textContent='Vänta…';form.setAttribute('aria-busy','true');form.querySelector('[data-error]').textContent='';try{await action(Object.fromEntries(new FormData(form)));}catch(error){formError(form,error);}finally{button.disabled=false;button.textContent=label;form.removeAttribute('aria-busy');}}
function formFooter(label){return `<p class="form-error" data-error role="alert"></p><button class="button full-width" type="submit">${label}</button>`;}
function field(label,name,type='text',extra=''){if(type==='password')return `<div class="field"><label for="${name}">${label}</label><div class="password-field"><input id="${name}" name="${name}" type="password" ${extra}><button type="button" class="password-toggle" aria-controls="${name}" aria-pressed="false">Visa</button></div></div>`;return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${extra}></div>`;}
function faqSection(){return `<section class="home-faq" aria-labelledby="faq-title"><div class="faq-heading"><p class="eyebrow">Lär känna VDK</p><h2 id="faq-title">Vanliga frågor</h2><p>Här hittar du svar på några av de vanligaste frågorna om Värmlands Domarkollektiv, medlemskap och hur du kan vara med och bidra.</p></div><div class="faq-list">${publicFaq.map((item,i)=>`<details class="faq-item" id="faq-${i+1}"><summary>${esc(item.question)}</summary><div class="faq-answer">${item.answer.map(block=>block.type==='list'?`<ul>${block.items.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:`<p>${esc(block.text)}</p>`).join('')}${item.link?`<p><a class="text-link" href="${esc(item.link.href)}">${esc(item.link.label)} →</a></p>`:''}</div></details>`).join('')}</div></section><section class="faq-contact card" aria-labelledby="faq-contact-title"><div><h2 id="faq-contact-title">Har du fler frågor?</h2><p>Hittar du inte svaret du söker? Hör gärna av dig till VDK.</p></div><div class="inline-actions"><a class="button" href="#/kontakt">Kontakta VDK</a><a class="button button-outline" href="#/medlemskap">Bli medlem</a><a class="button button-outline" href="#/medlemskap/stodmedlem">Stöd VDK</a></div></section>`;}
function home(){const loggedIn=!!user;return `<section class="hero"><img class="hero-image hero-image-light" src="assets/hero-light-referee.png" alt="" fetchpriority="high"><img class="hero-image hero-image-dark" src="assets/hero-dark.jpg" alt="" fetchpriority="high"><div class="hero-content"><p class="eyebrow">Värmlands Domarkollektiv</p><h1>TILLSAMMANS FÖR EN<br><span class="yellow">STARKARE DOMARKÅR</span></h1><p class="hero-intro">VDK samlar innebandydomare i Värmland för gemenskap, utveckling och trygghet – på och utanför planen.</p><div class="motto"><strong>AEQUALITAS PRO OMNIBUS</strong><em>Rättvisa för alla.</em></div><div class="hero-actions">${loggedIn?'<a class="button" href="#/mina-sidor">Mina sidor</a>':membershipMenu('hero-membership-menu')}<a class="button button-outline" href="#/om-vdk">Läs mer om VDK</a></div></div></section>
  <div class="container"><section class="pillars" aria-label="Det här står vi för">${[['people','Gemenskap','Ett starkare domarnätverk i Värmland.'],['growth','Utveckling','Videocoachning och kunskapsutbyte.'],['shield','Trygghet','Stöd för alla domare, hela säsongen.'],['whistle','Bättre hallmiljö','Tillsammans för en positiv innebandymiljö.']].map(([i,t,p])=>`<div class="pillar">${icon(i)}<div><h2>${t}</h2><p>${p}</p></div></div>`).join('')}</section>
  <section class="rule-banner" aria-labelledby="rule-generator-title"><div><p class="eyebrow">Träna ditt domarskap</p><h2 id="rule-generator-title">VDK Regelgenerator 2026</h2><p>${loggedIn?'Träna på matchsituationer och använd hela regelbanken med ditt godkända medlemskap.':'Prova tio enkla standardfrågor gratis. Fullversionen finns på Mina sidor för godkända aktiva medlemmar, stödmedlemmar och föreningsmedlemmar.'}</p></div><a class="button" href="${loggedIn?'/member-rules/':'#/regel-demo'}">${loggedIn?'Öppna regelgeneratorn':'Prova gratis demo'}</a></section><section class="home-cards" aria-label="Aktuellt från VDK"><article class="card card-light"><div class="card-heading"><h2>Senaste nytt</h2><a class="text-link" href="#/nyheter">Visa alla</a></div><p class="empty-news">Här samlar vi nyheter om föreningen, medlemskapet och kommande aktiviteter.</p><p class="empty-news">Inga nyheter är publicerade ännu.</p><a class="text-link" href="#/for-domare">Upptäck våra domarverktyg</a></article><article class="card quote-card"><span class="quote-mark" aria-hidden="true">“</span><blockquote>Bättre domare<br>skapar bättre matcher.</blockquote><cite>Värmlands Domarkollektiv</cite></article>${loggedIn?'<article class="card card-light"><h2>Dina medlemsverktyg</h2><p>Hitta dokument, kollegor och meddelanden på Mina sidor.</p><a class="button full-width" href="#/mina-sidor">Till Mina sidor</a></article>':`<article class="card card-light"><h2>Bli medlem idag</h2><ul class="benefit-list"><li>Stöd vår gemensamma utveckling</li><li>Ta del av videocoachning för seniorinnebandy</li><li>Bidra till en bättre hallmiljö</li><li>Var en del av Värmlands domarnätverk</li></ul><a class="button full-width" href="#/medlemskap">Se våra medlemskap</a></article>`}</section></div>`;}
function board(){return page('Styrelsen','Värmlands Domarkollektivs styrelse.',`<div class="content-grid board-grid">${[['Ordförande','Sören Johansson'],['Kassör','Alfred Särnehed'],['Sekreterare','Tim Weghammar'],['Ledamot','Ebba Knutsson'],['Ledamot','Johan Brunzell']].map(([role,name])=>`<article class="card"><p class="eyebrow">VDK:s styrelse</p><h2>${role}</h2><p>${esc(name)}</p>${role==='Ordförande'?'<p><a class="text-link" href="tel:+46735458489">073 545 84 89</a><br><a class="text-link" href="mailto:kontakt@vdk.nu">kontakt@vdk.nu</a></p>':''}</article>`).join('')}</div><div class="reading"><h2>Kontakta styrelsen</h2><p>Du når oss på <a class="text-link" href="mailto:kontakt@vdk.nu">kontakt@vdk.nu</a>.</p></div>`);}
function about(){return page('Av domare, för domare.','Som domare ska du inte behöva stå ensam.',`<div class="reading"><h2>Vilka vi är</h2><p>Värmlands Domarkollektiv, VDK, är en självständig ideell förening av och för innebandydomare i Värmland. Vi samlar domare för gemenskap, utveckling och trygghet – på och utanför planen.</p><p>Att vara domare innebär ansvar, press och ständiga beslut. Hos VDK vill vi göra erfarenheter, kunskap och kollegialt stöd lättare att nå, oavsett om du precis har börjat döma eller har många säsonger bakom dig.</p><h2>Varför VDK finns</h2><p>En stark domarverksamhet byggs också av dialog, återkoppling och möten mellan människor. VDK har vuxit fram ur frågor inom domarkåren om utveckling, kommunikation, delaktighet och stöd.</p><p>Vi vill skapa fler mötesplatser där domare kan dela erfarenheter, ställa frågor och bidra med idéer. Du ska känna att du tillhör en domarkår, även när du dömer med olika kollegor.</p><h2>Vad vi vill bygga tillsammans</h2><p>Verksamheten utvecklas med medlemmarna. Våra verktyg på Mina sidor finns redan; träffar, utbildning och aktiviteter växer fram utifrån behov och engagemang.</p></div><div class="content-grid"><article class="card"><h2>Gemenskap och erfarenhetsutbyte</h2><p>Vi vill knyta samman nya, unga och erfarna domare på olika nivåer. Domarsamlingar, regelträffar och sociala aktiviteter ska ge fler naturliga tillfällen att lära känna och stötta varandra.</p></article><article class="card"><h2>Utbildning mellan matcherna</h2><p>Regeldiskussioner, praktiska övningar och verkliga matchsituationer gör lärandet konkret. Regelgeneratorn och utvecklingstrappan ger stöd för att träna kunskap och reflektera över nästa steg.</p><a class="text-link" href="#/kunskapsnivaer">Utforska domarutvecklingen →</a></article><article class="card"><h2>Coachning och videocoachning</h2><p>Återkoppling ska hjälpa dig att förstå positionering, bedömningar, kommunikation och matchledning. Vi vill utveckla coachning och mentorskap där det som fungerar bra förstärks och nästa utvecklingspunkt blir tydlig.</p><p>På Mina sidor kan en videocoach sammanställa situationer med tidsangivelser, kommentarer och illustrationer på Domartavlan.</p></article><article class="card"><h2>Stöd till nya och unga domare</h2><p>Det ska vara okej att vara ny och ställa frågor utan prestige. Genom kontakt med erfarna kollegor, uppmuntran och stöd efter svåra matcher vill vi bidra till att fler känner trygghet och vill fortsätta döma.</p></article><article class="card"><h2>En tryggare hallmiljö</h2><p>Trygghet i hallen ger glädje i uppdraget. Genom dialog med föreningar och kunskap om domarrollen vill vi bidra till ett respektfullt matchklimat för domare, spelare och ledare.</p><p>Föreningsmedlemskapet ger två domarbesök à en timme under säsongen samt uppföljning och stöd till föreningens egna domare.</p><a class="text-link" href="#/medlemskap/foreningsmedlem">Läs om föreningsmedlemskap →</a></article><article class="card"><h2>Träning och aktiviteter</h2><p>Vi vill skapa gemensam löpträning, fysisk förberedelse inför löptest, regelorientering och sommaraktiviteter. Att träffas utanför matcherna stärker både gemenskapen och förberedelsen inför uppdraget.</p></article></div><div class="reading"><h2>Utveckling genom återkoppling</h2><p>Coachningens syfte är lärande och reflektion. VDK:s videocoachning avslutas med ”Two Stars and a Wish”: två styrkor och en tydlig utvecklingspunkt att ta med till nästa match.</p><p>Vi utvecklas tillsammans – på planen, genom samtal och med hjälp av video.</p><h2>Tillsammans med innebandyn i Värmland</h2><p>VDK är ett komplement till Värmlands Innebandyförbund. Vi har olika roller men ett gemensamt intresse: en trygg och utvecklande domarverksamhet. Vi har haft dialog med förbundet och fått positiv respons på föreningens ambition och verksamhetsidé.</p><p>VDK är varken ett alternativt förbund eller en fackförening. Officiell ranking och tillsättning hör till ansvarigt förbund. Kontrollera alltid dina matchuppdrag i iBIS och förbundets officiella kanaler.</p><h2>Ditt medlemskap gör skillnad</h2><p>Aktivt medlemskap kostar 100 kronor per säsong och bidrar till utbildning, coachning, gemenskap, aktiviteter och digitala verktyg. När betalningen har kontrollerats och medlemskapet godkänts öppnas medlemsfunktionerna på Mina sidor.</p><p>Där finns egna matcher, statistik över säsonger och domarkollegor, möjliga återbud, interna meddelanden, matchkommentarer och Domartavlan. Verktygens tillgång följer medlemskategori; fullversionen av regelgeneratorn är för aktiva medlemmar, stödmedlemmar och föreningsmedlemmar.</p><p>Även stödmedlemmar, föreningar och företag kan bidra. Företagsstöd är en gåva från 1 000 kronor som hjälper oss att utveckla verksamheten.</p><a class="button" href="#/medlemskap">Hitta ditt medlemskap eller stöd</a><h2>Delaktighet och öppenhet</h2><p>Idéer och förslag från medlemmarna hjälper oss att forma verksamheten. Aktiva medlemmar har rösträtt enligt stadgarna; stödmedlemmar har yttrande- och förslagsrätt men saknar rösträtt.</p><p>Här kan du läsa våra stadgar, se vilka som sitter i styrelsen och kontakta oss med frågor eller förslag.</p><div class="inline-actions"><a class="text-link" href="#/styrelsen">Styrelsen</a><a class="text-link" href="#/stadgar">Stadgar</a><a class="text-link" href="#/faq">Vanliga frågor</a><a class="text-link" href="mailto:kontakt@vdk.nu">kontakt@vdk.nu</a></div></div>`);}

const membershipNames={active:'Aktiv domare',support:'Stödmedlem',club:'Föreningsmedlem',business:'Företagsstöd'};
const money=value=>new Intl.NumberFormat('sv-SE').format(value)+' kr';
const membershipPaths={active:'aktiv-domare',support:'stodmedlem',club:'foreningsmedlem',business:'foretagsstod'};
const membershipAmounts={active:100,support:100,club:1500,business:1000};
function membershipChoices(){return Object.entries(membershipNames).map(([key,label])=>`<a href="#/medlemskap/${membershipPaths[key]}"><strong>${label}</strong><span>${key==='business'?'Gåva från ':''}${money(membershipAmounts[key])}${key==='business'?'':' / säsong'}</span></a>`).join('');}
function membershipMenu(id){return `<div class="membership-menu-wrap"><button type="button" class="button" data-membership-menu aria-expanded="false" aria-controls="${id}">Bli medlem</button><div class="membership-mini-menu" id="${id}" hidden><p>Välj medlemskap eller stöd</p>${membershipChoices()}</div></div>`;}
function statutesLink(){return '<div class="inline-actions"><a class="text-link" href="#/stadgar">Läs VDK:s stadgar</a><a class="text-link" href="'+esc(config.statutesUrl||'assets/stadgar-vdk.pdf')+'" download>Ladda ner stadgarna (PDF)</a></div>';}

function sharedQr(category){const paymentNote=category==='club'?'Ändra beloppet i Swish till 1 500 kr och ange föreningens namn i meddelandet.':category==='business'?'Ändra beloppet i Swish till din gåva, minst 1 000 kr, och ange företagsstöd samt företagets namn i meddelandet.':'Kontrollera beloppet 100 kr och ange ditt namn i meddelandet.';return `<aside class="card qr-card"><h2>Betala med Swish</h2><object class="membership-qr-pdf" data="${esc(config.membershipQrPdf)}#toolbar=0&navpanes=0&view=Fit" type="application/pdf" aria-label="VDK:s gemensamma Swish-kod"><p>Öppna PDF:en via länken nedan för att se QR-koden.</p></object><a class="button secondary qr-open" href="${esc(config.membershipQrPdf)}" target="_blank" rel="noopener">Öppna Swish-koden (PDF)</a><p>Swishnummer: <strong>123 149 49 88</strong></p><p>Samma QR-kod används för alla medlemskategorier och företagsstöd. Den fyller i 100 kr och ”Medlemsavgift 2026/27”.</p><p><strong>${paymentNote}</strong> Kontrollera mottagaren innan du godkänner betalningen.</p></aside>`;}
function membership(){return page('Välj medlemskap eller stöd.','Det finns flera sätt att vara en del av VDK. Välj det som passar dig för att läsa mer.',`<div class="membership-chooser">${membershipChoices()}</div><p class="notice">Aktiva medlemmar har rösträtt enligt stadgarna. Stödmedlemmar kan komma med förslag och har ingen rösträtt. Företagsstöd är en gåva.</p>${statutesLink()}`);}
const membershipInformation={
  active:{title:'Aktiv medlem',intro:'För dig som är aktiv innebandydomare och vill utvecklas tillsammans med Värmlands domarkår.',body:`<h2>Gemenskap på och utanför planen</h2><p>Som aktiv medlem är du en del av ett kollektiv som delar erfarenheter, stöttar varandra och arbetar för en bättre hallmiljö. Du får en plats för din egen domarutveckling och för samtal med kollegor.</p><ul class="benefit-list"><li>Gemenskap och kollegialt stöd</li><li>Mina sidor med verktyg för din domarutveckling</li><li>Videocoachning för seniorinnebandy</li></ul><h2>Din röst i föreningen</h2><p>Som aktiv medlem har du rösträtt när du uppfyller stadgarnas krav för aktivt medlemskap och rösträtt. Du kan vara med och påverka VDK:s riktning och utveckling.</p><h2>Varför ditt medlemskap är viktigt</h2><p>En stark domarkår byggs av domare som engagerar sig. Ditt medlemskap bidrar till att vi kan samla kunskap, utveckla våra verktyg och skapa en tryggare vardag för dem som leder matcherna.</p>`},
  support:{title:'Stödmedlem',intro:'För dig som vill stötta domarna och bidra till en positiv innebandymiljö i Värmland.',body:`<h2>Du behöver inte stå på planen för att göra skillnad</h2><p>Som stödmedlem hjälper du VDK att skapa gemenskap, uppmuntra domare och arbeta för respekt i hallarna. Du kan vara förälder, ledare, tidigare domare eller helt enkelt någon som tycker att domarnas arbete är viktigt.</p><h2>Förslag och idéer är välkomna</h2><p>Du har möjlighet att komma med förslag och bidra med dina erfarenheter. Stödmedlemskapet ger ingen rösträtt. Medlemsrättigheterna regleras i VDK:s stadgar.</p><h2>Varför ditt stöd är viktigt</h2><p>Bakom varje match finns människor som behöver känna sig trygga i sitt uppdrag. Ditt stöd hjälper oss att bygga ett nätverk där domare får uppmuntran, kunskapsutbyte och kollegor att vända sig till.</p>`},
  club:{title:'Föreningsmedlem',intro:'En närmare dialog med domarkåren och omtanke om föreningens egna domare.',body:`<h2>Två domarbesök under säsongen</h2><p>För 1 500 kr får er förening två besök av en domare, <strong>en timme per besök</strong>. Vi planerar tillfällena tillsammans med er.</p><p>Här finns tid att ställa frågor, diskutera regler och få klarhet i sådant som annars lätt hamnar i skuggan av matchens puls. Samtalet sker vid ett neutralt tillfälle, fristående från en enskild matchhändelse.</p><h2>Vi tar hand om era föreningsdomare</h2><p>Vi följer upp, åker ut och stöttar era domare. Med ett positivt bemötande och uppmuntran vill vi hjälpa dem att känna sig trygga, våga utvecklas och trivas med uppdraget.</p><ul class="benefit-list"><li>Två domarbesök à en timme</li><li>Frågor, regelkunskap och dialog i lugn miljö</li><li>Uppföljning och stöd till föreningsdomarna</li><li>En kontakt med Värmlands Domarkollektiv</li></ul><h2>Varför föreningens engagemang är viktigt</h2><p>När föreningar och domare lär känna varandra ökar förståelsen för varandras uppdrag. Tillsammans kan vi skapa en hallmiljö där nya domare får en bra start och fler vill fortsätta döma.</p><p>Medlemskap och representation regleras i VDK:s stadgar.</p>`},
  business:{title:'Företagsstöd',intro:'En gåva till domarutveckling och en bättre innebandymiljö i Värmland. Ni väljer beloppet, från 1 000 kr.',body:`<h2>Stötta människorna som gör matchen möjlig</h2><p>Varje match behöver domare som känner sig trygga och vill fortsätta med sitt uppdrag. Er gåva bidrar till VDK:s arbete med gemenskap, uppföljning, stöd och utveckling för domarkåren.</p><h2>Valfri gåva från 1 000 kr</h2><p>Ni väljer själva hur mycket ni vill ge, med ett minsta belopp på 1 000 kr. Företagsstöd är en gåva och ger inte medlemskap eller rösträtt.</p><h2>Varför ert stöd är viktigt</h2><p>Ett lokalt företag kan göra konkret skillnad för den lokala idrotten. Genom att stötta domarna bidrar ni till en miljö där fler vill engagera sig, där nya domare får uppmuntran och där vi möter varandra med respekt.</p><p>Om ni vill kan vi presentera er som ett företag som stöttar VDK. Önskar ni ett särskilt sponsorsamarbete tar vi gärna en separat dialog.</p>`}
};
function applicationForm(category,s){const business=category==='business';const org=['club','business'].includes(category);const label=business?'Anmäl företagsstöd':'Ansök om '+(category==='active'?'aktivt medlemskap':category==='support'?'stödmedlemskap':'föreningsmedlemskap');return `<div class="card form-card" id="membership-application"><h2>${label}</h2>${business?'':'<p>Du kan skapa och aktivera ditt konto på Mina sidor direkt. Medlemsfunktionerna låses upp när VDK har registrerat din betalning och godkänt medlemskapet.</p>'}<form id="membership-form"><input type="hidden" name="category" value="${category}"><input type="hidden" name="season" value="${esc(s.season)}">${org?field(category==='club'?'Föreningens namn':'Företagets namn','organization','text','required maxlength="160"'):''}${business?field('Gåvans belopp (kronor, minst 1 000)','amount','number','required min="1000" max="10000000" step="1" value="1000"'):''}${field(org?'Kontaktperson':'Namn','name','text','required autocomplete="name" maxlength="120"')}${field('E-postadress','email','email','required autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" maxlength="254"')}<label class="check-label"><input type="checkbox" name="consent" required><span>${business?'Jag vill lämna företagsstöd':'Jag ansöker om medlemskap'} och har läst <a href="#/integritet" target="_blank" rel="noopener">hur VDK behandlar mina uppgifter (ny flik)</a>.</span></label>${formFooter(business?'Skicka anmälan':'Skicka medlemsansökan')}</form></div>`;}
async function membershipDetail(category){const info=membershipInformation[category];const s=await loadSettings();return page(info.title,info.intro,`<a class="text-link" href="#/medlemskap">Alla medlemskap och stöd</a><div class="membership-detail-layout"><article class="reading"><div class="membership-price">${category==='business'?'Från ':''}${money(membershipAmounts[category])}<span>${category==='business'?' / gåva':' / säsong'}</span></div>${info.body}${category==='business'?'':statutesLink()}</article><div class="membership-detail-aside">${applicationForm(category,s)}${sharedQr(category)}</div></div>`);}
function statutes(){const sections=statutesParagraphs.map((p,i)=>({...p,id:'stadge-'+i}));return page(statutesParagraphs[0].text,'Läs stadgarna direkt här eller ladda ner dem som PDF.',`<div class="inline-actions"><a class="button" href="${esc(config.statutesUrl||'assets/stadgar-vdk.pdf')}" download>Ladda ner stadgarna (PDF)</a><a class="text-link" href="#/medlemskap">Medlemskap och stöd</a></div><div class="statutes-layout"><nav class="card statutes-contents" aria-label="Stadgarnas innehåll"><h2>Innehåll</h2>${sections.filter(p=>p.kind==='heading').map(p=>`<a href="#${p.id}" data-statute-target="${p.id}">${esc(p.text)}</a>`).join('')}</nav><article class="reading statutes-text" aria-label="Fullständiga stadgar">${sections.slice(1).map(p=>p.kind==='heading'?`<h2 id="${p.id}" tabindex="-1">${esc(p.text)}</h2>`:p.kind==='subheading'?`<h3 id="${p.id}">${esc(p.text)}</h3>`:`<p>${esc(p.text).replace(/\n/g,'<br>')}</p>`).join('')}</article></div>`);}
document.addEventListener('click',event=>{const link=event.target.closest('[data-statute-target]');if(!link)return;event.preventDefault();const target=document.getElementById(link.dataset.statuteTarget);target?.focus({preventScroll:true});target?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});


function referees(){return page('Ditt domarskap. Din utveckling.','Mina sidor samlar verktygen som hjälper VDK-medlemmar att följa och utveckla sitt domarskap.',`<div class="content-grid"><article class="card"><h2>Mina matcher</h2><p>Dina egna matcher, samlade i en personlig vy. Matchunderlag läggs till när kopplingen till den publika innebandydatan är verifierad.</p></article><article class="card"><h2>Min statistik</h2><p>Se matchhändelser och utvisningskategorier per säsong. Filtrera på domarkollega och reflektera över nivån ni sätter tillsammans.</p></article><article class="card"><h2>Möjliga återbud</h2><p>Matcher med färre än två offentligt synliga domare kan bli en signal att kontrollera uppdraget i iBIS. En saknad domare i publik data är inte ett bekräftat återbud.</p></article><article class="card"><h2>Videocoachning</h2><p>För seniorinnebandy. Gå direkt till kommenterade situationer, läs coachens återkoppling och diskutera bedömningarna.</p></article></div><div class="reading"><h2>Verktyg för utveckling</h2><p><a class="text-link" href="#/kunskapsnivaer">Se förslaget till VDK:s kunskapsnivåer</a> · <a class="text-link" href="#/regel-demo">Prova regelgeneratorns demo</a></p><p>Matchstatistiken beskriver händelser i de matcher du har dömt. Den säger inte vilken domare som fattade ett enskilt beslut. VDK sammanställer Värmlands röda pojk- och flickserier, seniorserier och HJ17, DJ17, HJ18 och DJ18. Endast matcher spelade inom vårt område ingår, inklusive Karlskoga, Degerfors, Billingsfors och Åmål. Varje match räknas en gång.</p><p>Matchprogram, resultat, tabeller och tillsättning finns fortsatt hos <a class="text-link" href="https://www.innebandy.se/" target="_blank" rel="noopener">innebandy.se</a> och i iBIS.</p><div class="inline-actions"><a class="button" href="#/mina-sidor">Till Mina sidor</a><a class="button button-outline" href="#/medlemskap">Bli medlem</a></div></div>`);}
function sponsors(){return page('Stärk domarna. Stärk innebandyn.','Som sponsor kan du bidra till gemenskap, domarutveckling och en bättre hallmiljö i Värmland.',`<div class="content-grid"><article class="card"><h2>Bli en del av VDK</h2><p>Vill din verksamhet stötta Värmlands innebandydomare? Kontakta oss så pratar vi om hur ett samarbete kan se ut.</p><a class="button" href="mailto:kontakt@vdk.nu?subject=Sponsorsamarbete%20med%20VDK">Prata med oss om sponsring</a></article><article class="card">${empty('Våra samarbeten','Godkända sponsorsamarbeten presenteras här när de är klara.')}</article></div>`);}
function news(){return page('Nyheter från VDK.','Föreningsnyheter, medlemsinformation och aktiviteter.',`<div class="card">${empty('Inga nyheter är publicerade ännu.','När vi har något nytt att dela hittar du det här. Under tiden kan du läsa mer om medlemskapet och vår verksamhet.')}<div style="text-align:center"><a class="button button-outline" href="#/om-vdk">Läs om VDK</a></div></div>`);}
function contact(){return page('Vi hörs.','Frågor om medlemskap, videocoachning eller samarbete? Hör av dig till VDK.',`<div class="content-grid"><article class="card"><p class="eyebrow">E-post</p><h2>Kontakta kollektivet</h2><a class="contact-address" href="mailto:kontakt@vdk.nu">kontakt@vdk.nu</a><p style="margin-top:1.5rem">Värmland, Sverige</p></article><article class="card"><h2>Vad gäller ditt ärende?</h2><p>Skriv gärna om frågan handlar om medlemskap, din domarportal, videocoachning eller sponsring. Då blir det lättare för oss att hjälpa dig.</p><a class="button" href="mailto:kontakt@vdk.nu">Skriv till oss</a></article></div>`);}
function privacy(){return page('Dina uppgifter hos VDK.','Medlemsuppgifter används för medlemskapet och din egen domarutveckling.',`<div class="reading"><h2>Vilka uppgifter vi behandlar</h2><p>VDK behandlar namn, e-postadress, en valfri profilbild och frivilliga kontaktuppgifter för samåkning, säsongsmedlemskap, betalningsstatus och kontobehörigheter. Om du använder domarverktygen kan även kopplingen till dina matcher, din statistik och videocoachningar behandlas.</p><h2>Vem får tillgång?</h2><p>Du väljer själv om profilens kontaktuppgifter och bild ska visas för andra godkända VDK-medlemmar. De visas inte offentligt. Ditt kontos inloggningsmejl delas inte automatiskt.</p><p>Du ser dina egna medlemsuppgifter och matcher. Behöriga administratörer hanterar medlemsregistret. Videocoacher ser de uppdrag och situationer de har tilldelats. Videocoachning är endast tillgänglig för berörda medlemmar och behöriga coacher.</p><h2>Matchstatistik</h2><p>VDK sammanställer offentliga matchprotokoll från Värmlands seniorserier. Medlemmar kan se gemensam statistik och sina egna matchkopplingar. Matchhändelser beskriver inte vilken av domarna som fattade beslutet. En match räknas en gång i den gemensamma statistiken även om två VDK-medlemmar har dömt den.</p><h2>Kontosäkerhet och kakor</h2><p>Lösenord lagras som säkra envägsvärden. En nödvändig sessionskaka används för inloggning. Webbplatsen använder ingen annons- eller analysmätning. Typsnitt hämtas från Google Fonts, vilket innebär att din webbläsare kontaktar Google vid sidvisning.</p><h2>Frågor, rättelse och radering</h2><p>Kontakta <a class="text-link" href="mailto:kontakt@vdk.nu">kontakt@vdk.nu</a> om du vill få tillgång till dina uppgifter, rätta dem eller begära radering.</p>${notice('Inför öppning av medlemstjänsten kompletterar VDK informationen med ansvarig förening, rättslig grund och beslutade lagringstider.')}</div>`);}
function login(){return `<section class="page container auth-page"><div class="login-wrap"><p class="eyebrow">Mina sidor</p><h1>Logga in</h1><p class="lead">Använd e-postadressen och lösenordet till ditt VDK-konto.</p><div class="card form-card"><form id="login-form">${field('E-postadress','email','email','required autocomplete="username" inputmode="email" autocapitalize="none" spellcheck="false"')}${field('Lösenord','password','password','required autocomplete="current-password"')}<a class="text-link auth-reset" href="#/aterstall">Glömt lösenord?</a>${formFooter('Logga in')}</form></div><div class="card auth-secondary"><h2>Ny hos VDK?</h2><p>Registrera dig, öppna mejlet från VDK och välj ditt lösenord. Du kan logga in innan betalningen är godkänd.</p><a class="button button-outline full-width" href="#/registrera">Registrera dig</a></div><p class="auth-help">Har du redan registrerat dig? Öppna aktiveringslänken i mejlet från VDK. Kontrollera även skräpposten. <a class="text-link" href="mailto:kontakt@vdk.nu">Kontakta oss</a> om mejlet saknas.</p></div></section>`;}
function passwordPage(reset=false){return `<section class="page container auth-page"><div class="login-wrap"><p class="eyebrow">Mina sidor</p><h1>${reset?'Nytt lösenord':'Aktivera ditt konto'}</h1><p class="lead">Välj ett lösenord med minst 12 tecken. Därefter kan du logga in.</p><div class="card form-card"><form id="password-form" data-reset="${reset}">${field('Lösenord','password','password','required minlength="12" maxlength="256" autocomplete="new-password"')}${field('Upprepa lösenordet','confirm','password','required minlength="12" maxlength="256" autocomplete="new-password"')}${formFooter(reset?'Spara lösenord':'Aktivera konto')}</form></div><a class="text-link auth-back" href="#/logga-in">Till inloggningen</a></div></section>`;}
function resetPage(){return `<section class="page container auth-page"><div class="login-wrap"><h1>Glömt lösenord?</h1><p class="lead">Ange e-postadressen till ditt konto så skickar vi en länk för att välja ett nytt lösenord.</p><div class="card form-card"><form id="reset-form">${field('E-postadress','email','email','required autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false"')}${formFooter('Skicka återställningslänk')}</form></div><a class="text-link auth-back" href="#/logga-in">Till inloggningen</a></div></section>`;}
async function registration(category){if(!category)return page('Registrera dig','Välj ditt medlemskap. Sedan fyller du i namn och e-postadress.',`<div class="membership-chooser">${Object.entries(membershipNames).map(([key,label])=>`<a href="${key==='business'?'#/medlemskap/foretagsstod':'#/registrera/'+membershipPaths[key]}"><strong>${label}</strong><span>${key==='business'?'Gåva från '+money(membershipAmounts[key]):money(membershipAmounts[key])+' / säsong'}</span></a>`).join('')}</div><p class="auth-help">Har du redan ett konto? <a class="text-link" href="#/logga-in">Logga in</a></p>`);const settings=await loadSettings();return page('Registrera dig',membershipNames[category]+' · '+money(membershipAmounts[category])+' / säsong',`<div class="auth-registration"><div>${applicationForm(category,settings)}<p class="auth-help">Har du redan ett konto? <a class="text-link" href="#/logga-in">Logga in</a></p></div><aside class="card"><h2>Så kommer du igång</h2><ol class="steps"><li><div><strong>Registrera dig</strong><span>Fyll i namn och e-postadress.</span></div></li><li><div><strong>Välj lösenord via mejlet</strong><span>Öppna aktiveringslänken från VDK. Du kan sedan logga in.</span></div></li><li><div><strong>Betala medlemsavgiften</strong><span>Betalningsuppgifterna visas efter registreringen. Medlemsfunktionerna öppnas när VDK godkänt betalningen.</span></div></li></ol><a class="text-link" href="#/medlemskap/${membershipPaths[category]}">Läs mer om medlemskapet</a></aside></div>`);}
function updateAccountNavigation(){const link=document.querySelector('.account-link');link.textContent=user?'Mina sidor':'Logga in';link.href=user?'#/mina-sidor':'#/logga-in';document.querySelector('[data-logout]').hidden=!user;document.querySelector('.nav-membership').hidden=!!user;document.querySelector('[data-member-documents]').hidden=!user;document.querySelector('[data-member-profile]').hidden=!user;document.querySelectorAll('.site-footer a[href="#/medlemskap"],.site-footer a[href="#/mina-sidor/dokument"]').forEach(a=>{a.href='#/medlemskap';a.textContent='Bli medlem';a.hidden=!!user;});}
async function logout(button){if(button.disabled)return;button.disabled=true;button.textContent='Loggar ut…';try{await api('/auth/logout',{method:'POST',body:{}});user=null;updateAccountNavigation();history.replaceState(null,'','#/logga-in');await route();toast('Du är utloggad.');}catch(error){toast(error.message);}finally{button.disabled=false;button.textContent='Logga ut';}}
const portalTabs=[['','Mitt kontrollrum'],['matcher','Mina matcher'],['kommentarer','Matcher med kommentar'],['statistik','Min statistik'],['forbund','Förbundsmatcher'],['varmland','Värmlands statistik'],['aterbud','Möjliga återbud'],['medlemmar','Medlemmar'],['meddelanden','Meddelanden'],['sok-matcher','Sök matcher'],['domartavlan','Domartavlan'],['video','Mina videocoachningar'],['medlemskap','Mitt medlemskap']];

function statisticsSelect(label,name,rows,selected,emptyLabel,prefix){
 return `<div class="field"><label for="${prefix}-${name}">${label}</label><select id="${prefix}-${name}" name="${name}">${emptyLabel?`<option value="">${emptyLabel}</option>`:''}${rows.map(r=>`<option value="${esc(r.id)}" ${String(r.id)===selected?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>`;
}
function statisticsFilter(id,fields,against){
 return `<details id="statistics-filters" class="statistics-filter-panel" open><summary>Välj urval <span>Säsong, lag och domare</span></summary><form id="${id}" class="statistics-filter"><div class="statistics-filter-fields">${fields}</div><label class="check-label statistics-check"><input type="checkbox" name="against" value="true" ${against?'checked':''}><span>Visa bara utvisningar mot valt lag<small>Välj ett lag ovan för att använda detta alternativ.</small></span></label><p class="form-error" data-filter-error role="alert" hidden></p><button class="button" type="submit">Visa statistik</button></form></details>`;
}
function foldSection(title,body){return `<details class="statistics-fold"><summary>${title}</summary><div class="statistics-fold-body">${body}</div></details>`;}
function statisticsResults(d,season,{regional=false,team='',against=false,competition='',code='',scope='all'}={}){
 return `<section id="statistics-results" class="statistics-results" aria-labelledby="statistics-result-heading"><h2 id="statistics-result-heading" tabindex="-1">Resultat – ${season==='all'?'alla säsonger':esc(season)}</h2><p class="statistics-result-note" role="status">Urvalet omfattar ${d.matches} matcher. ${against?'Visar utvisningar mot det valda laget.':'Visar utvisningshändelser i de valda matcherna.'}</p>${!regional?foldSection('Utveckling över säsongerna',seasonComparison(d,code)):''}<div class="card statistics-summary">${statsView(d)}</div>${d.matches?`${foldSection('Matcher i urvalet · '+d.matches,matchTable(d.matchList,{regional}))}`:''}${!regional&&d.colleagueSummary?.length?`${foldSection('Mina domarkollegor i urvalet',colleagueTable(d.colleagueSummary,season,team,against,competition,code,scope))}`:''}</section>`;
}
const statisticsSeasons=['2026/27','2025/26','2024/25','2023/24','2022/23'];
async function regionalStats(){
 const params=new URLSearchParams(location.hash.split('?')[1]);if(!params.has('season'))params.set('season','2025/26');
 const d=await api('/regional-statistics?'+params),season=params.get('season'),against=params.get('against')==='true';
 const select=(label,name,rows,all)=>statisticsSelect(label,name,rows,params.get(name),all,'region');
 const fields=select('Säsong','season',[...new Set([...statisticsSeasons,...d.seasons])].sort((a,b)=>b.localeCompare(a)).map(x=>({id:x,name:x})),null)+select('Serie','competition',d.allCompetitions.map(name=>({id:name,name})),'Alla serier')+select('Lag','team',d.allTeams,'Alla lag')+select('Domare','referee',d.referees,'Alla domare')+select('Domarkollega','coReferee',d.referees,'Alla kollegor')+select('Utvisning','code',(d.penaltyTypes||[]).map(t=>({id:t.id,name:t.id+' · '+t.name})),'Alla utvisningar');
 return `<h2>Värmlands statistik</h2><p>Matcher spelade i Värmland samt Karlskoga, Degerfors, Billingsfors och Åmål. Röda pojk- och flickserier, seniorserier och HJ17, DJ17, HJ18 och DJ18 ingår. Välj serie för att hålla olika nivåer åtskilda.</p>${statisticsFilter('regional-filter',fields,against)}${statisticsResults(d,season,{regional:true,against})}<p class="stats-updated">${d.lastUpdate?'Senast uppdaterat: '+date(d.lastUpdate.finished_at)+'. ':''}${d.lastUpdate?.status==='partial'?'Vissa protokoll kunde inte läsas. ':''}Saknade protokoll räknas inte som noll. Statistiken gäller domarparets matchhändelser.</p>`;
}
async function personalMatches(){
 const settings=await loadSettings(),{matches}=await api('/matches'),params=new URLSearchParams(location.hash.split('?')[1]||''),seasons=[...new Set([settings.season,...statisticsSeasons,...matches.map(m=>m.season)])].sort((a,b)=>b.localeCompare(a)),requested=params.get('season'),selected=seasons.includes(requested)?requested:settings.season,visible=matches.filter(m=>m.season===selected);
 return `<h2>Mina matcher</h2><p>Årets säsong visas från början. Välj en tidigare säsong för att öppna dess matcher.</p><div class="card">${statisticsSelect('Säsong','season',seasons.map(season=>({id:season,name:season})),selected,null,'matches')}</div>${visible.length?foldSection(esc(selected)+' · '+visible.length+' matcher',matchTable(visible)):`<div class="card">${empty('Inga matcher för den här säsongen.','Välj en annan säsong för att se tidigare matcher. Matcher visas när de har hämtats och kopplats till ditt konto.')}</div>`}`;
}
async function personalStats(){
 const federalOnly=location.hash.startsWith('#/mina-sidor/forbund');const s=await loadSettings(),params=new URLSearchParams(location.hash.split('?')[1]),season=params.get('season')||'all',colleague=params.get('colleague')||'',team=params.get('team')||'',against=params.get('against')==='true',competition=params.get('competition')||'',code=params.get('code')||'';
 const scope=federalOnly?'federal':params.get('scope')||'all';const d=await api('/statistics?'+new URLSearchParams({season,colleague,team,competition,code,scope,against:String(against)}));
 const fields=(federalOnly?'<input type="hidden" name="scope" value="federal">':statisticsSelect('Matchnivå','scope',[{id:'all',name:'Alla mina matcher'},{id:'district',name:'Distriktsserier'},{id:'federal',name:'Förbundsserier'}],scope,null,'stats'))+statisticsSelect('Säsong','season',[{id:'all',name:'Alla säsonger'},...[...new Set([s.season,...statisticsSeasons,...d.seasons])].map(x=>({id:x,name:x}))],season,null,'stats')+statisticsSelect('Domarkollega','colleague',[...new Set([...d.colleagues,...(colleague?[colleague]:[])])].map(x=>({id:x,name:x})),colleague,'Alla kollegor','stats')+statisticsSelect('Lag','team',d.teams||[],team,'Alla lag','stats')+statisticsSelect('Serie','competition',(d.competitions||[]).map(x=>({id:x,name:x})),competition,'Alla serier','stats')+statisticsSelect('Utvisningstyp','code',(d.penaltyTypes||[]).map(t=>({id:t.id,name:t.id+' · '+t.name})),code,'Alla utvisningar','stats');
 return `<h2>${federalOnly?'Mina förbundsmatcher':'Min statistik'}</h2><p>${federalOnly?'Dina förbundsmatcher i hela Sverige, inklusive matcher utanför Värmland.':'Dina distrikts- och förbundsmatcher samlas här.'} Följ din statistik över säsongerna. Välj Alla säsonger för att jämföra år, och kombinera domarkollega, utvisningstyp, lag och serie.</p>${d.importProgress?notice('Matchimport pågår. Underlaget fylls på: '+d.importProgress.checked+' av '+d.importProgress.total+' '+(d.importProgress.phase==='planning'?'serier inventerade.':'matchprotokoll genomgångna.')+' Uppdatera sidan för att se nya resultat.'):''}${statisticsFilter('stats-filter',fields,against)}${statisticsResults(d,season,{team,against,competition,code,scope})}<p class="stats-updated">${d.lastUpdate?'Senast uppdaterat: '+date(d.lastUpdate.finished_at)+'. ':''}${d.lastUpdate?.status==='partial'?'Vissa protokoll kunde inte läsas. ':''}Statistiken beskriver händelser i dina matcher och visar inte vilken domare som fattade ett enskilt beslut.${against&&d.unknownTeamPenalties?' '+d.unknownTeamPenalties+' händelser saknar lagkoppling och ingår inte i urvalet mot laget.':''}</p>`;
}
async function applyStatisticsFilters(form,path){
 const params=new URLSearchParams(new FormData(form)),against=form.querySelector('[name="against"]').checked;
 params.set('against',String(against));const error=form.querySelector('[data-filter-error]');error.hidden=true;
 if(against&&!params.get('team')){error.textContent='Välj ett lag för att se utvisningar mot laget.';error.hidden=false;return;}
 if(params.get('referee')&&params.get('referee')===params.get('coReferee')){error.textContent='Välj två olika domare, eller lämna Domarkollega som Alla kollegor.';error.hidden=false;return;}
 const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Hämtar statistik…';
 const hash='#'+path+'?'+params;if(location.hash!==hash)history.pushState(null,'',hash);
 // Explicit rendering also handles another search with an unchanged query.
 await route({focusResults:true});
}


async function availabilityView(){
 const q=new URLSearchParams(location.hash.split('?')[1]||''),d=await api('/availability?'+q);
 const fields=statisticsSelect('Serie','competition',d.competitions,q.get('competition')||'','Alla serier','vacancy')+statisticsSelect('Publicerade domare','count',[{id:'0',name:'Ingen domare'},{id:'1',name:'En domare'}],q.get('count')||'','Noll eller en domare','vacancy')+['team','referee','from','to'].map(n=>`<div class="field"><label for="vacancy-${n}">${({team:'Lag',referee:'Publicerad domarkollega',from:'Från datum',to:'Till datum'})[n]}</label><input id="vacancy-${n}" name="${n}" type="${n==='from'||n==='to'?'date':'search'}" value="${esc(q.get(n)||'')}" ${n==='from'||n==='to'?`min="${d.from}" max="${d.to}"`:''}></div>`).join('');
 return `<h2>Möjliga återbud</h2><p>Röd serie för pojkar och flickor, H5–H2, D3–D1 samt HJ17 och DJ17. Matcher i Värmland, Karlskoga, Degerfors, Billingsfors och Åmål.</p>${notice('Saknade publicerade domarnamn är möjliga återbud, inte bekräftade lediga uppdrag. Kontrollera tillsättningen i iBIS. Ungdomsserier kan ha annan domarbemanning.')}<form id="availability-filter" class="card"><div class="content-grid">${fields}</div><button class="button" type="submit">Visa matcher</button></form><h3 id="statistics-result-heading" tabindex="-1">${d.matches.length} matcher i urvalet</h3><p>Period: ${d.from} – ${d.to}. Uppdateras varje dag kl. 03 svensk tid.</p><p>${d.updatedAt?'Senast kontrollerat: '+esc(new Date(d.updatedAt).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm'})): 'Första hämtningen pågår.'}${d.loading?' En uppdatering pågår.':''}${d.unverified?' '+d.unverified+' matcher kunde inte verifieras och visas inte.':''}</p>${d.matches.map(m=>`<article class="card" style="margin-bottom:1rem;overflow-wrap:anywhere"><span class="badge">${esc(m.competition)}</span><h3>${esc(m.home)} – ${esc(m.away)}</h3><p>${esc(/^[0-9-]+T[0-9:.]+$/.test(m.starts_at)?m.starts_at.replace('T',' ').slice(0,16):new Date(m.starts_at).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm'}))}<br>${esc(m.venue)}</p><p><strong>${m.referees.length?'Publicerad domarkollega: '+esc(m.referees[0]):'Ingen domare publicerad'}</strong></p><a class="text-link" href="${esc(m.source_url)}" target="_blank" rel="noopener">Kontrollera matchen</a></article>`).join('')||'<p>Inga matcher i urvalet. Prova en annan serie eller ett annat filter.</p>'}`;
}
function seasonComparison(d,code){
 const selected=code?(d.penaltyTypes||[]).find(t=>String(t.id)===code)?.name:'Alla utvisningstyper',format=n=>Number(n).toLocaleString('sv-SE',{maximumFractionDigits:2});
 const table=(rows,colleagues=false)=>`<div class="card table-wrap statistics-table-wrap"><table class="statistics-table"><thead><tr><th>Säsong</th>${colleagues?'<th>Domarkollega</th>':''}<th>Matcher</th><th>Händelser</th><th>Snitt / match</th></tr></thead><tbody>${rows.map(r=>`<tr><td data-label="Säsong">${esc(r.season)}</td>${colleagues?`<td data-label="Domarkollega">${esc(r.colleague||'Ej angiven')}</td>`:''}<td data-label="Matcher">${r.matches}</td><td data-label="Händelser">${r.penalties}</td><td data-label="Snitt / match">${format(r.penaltiesPerMatch)}</td></tr>`).join('')}</tbody></table></div>`;
 return `<section aria-labelledby="season-comparison-title"><h2 id="season-comparison-title">Utveckling över säsongerna</h2><p>${esc(selected||code)}. Alla filter ovan gäller jämförelsen. Snittet räknas på samtliga matcher i urvalet, även matcher utan den valda utvisningen. Pågående säsong har ett kortare underlag.</p>${d.seasonSummary?.length?table(d.seasonSummary):'<p>Inga matcher i urvalet.</p>'}${d.seasonColleagues?.length?`<details class="statistics-filter-panel"><summary>Jämför domarkollegor per säsong</summary>${table(d.seasonColleagues,true)}</details>`:''}</section>`;
}

function messageItems(messages){return messages.map(m=>`<article class="message-bubble ${m.sender_id===user.id?'message-mine':''}"><p class="message-body">${esc(m.body)}</p><small>${m.sender_id===user.id?'Du':'Mottaget'} · ${esc(new Date(m.created_at).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm'}))}</small></article>`).join('')||'<p>Inga meddelanden ännu. Skriv det första nedan.</p>';}
const broadcastGroups={all:'Alla medlemmar',active:'Alla aktiva medlemmar',club:'Alla föreningsmedlemmar',support:'Alla stödmedlemmar'};
async function messagesView(){
 const d=await api('/messages'),q=new URLSearchParams(location.hash.split('?')[1]||''),peer=Number(q.get('to')),before=q.get('before');messageUnread=d.unread;let conversation='';const channel=q.get('to'),isBroadcast=Object.hasOwn(broadcastGroups,channel);
 if(channel==='suggestions'||isBroadcast){
 if(isBroadcast&&!user.roles.includes('ADMIN'))return notice('Endast admin kan skriva till alla medlemmar.','error');
 let inbox='';if(channel==='suggestions'&&user.roles.includes('ADMIN')){const data=await api('/messages/suggestions'+(before?'?before='+encodeURIComponent(before):''));inbox=`<h3>Förslagsinkorg – endast admin</h3>${data.suggestions.map(x=>`<article class="message-bubble"><strong>${esc(x.name)}</strong><p class="message-body">${esc(x.body)}</p><small>${esc(new Date(x.created_at).toLocaleString('sv-SE'))}</small></article>`).join('')||'<p>Inga förslag ännu.</p>'}${data.hasOlder?`<a class="text-link" href="#/mina-sidor/meddelanden?to=suggestions&before=${data.suggestions.at(-1).id}">Äldre förslag</a>`:''}`;}
 conversation=`<section class="card"><h3>${isBroadcast?esc(broadcastGroups[channel]):'Lämna förslag'}</h3><p>${isBroadcast?'Skickas som ett privat meddelande till varje medlem i den valda gruppen med ett aktivt konto. Svar går bara till dig.':'Ditt förslag skickas till en separat inkorg som endast administratörer kan läsa.'}</p><form id="special-message-form" data-channel="${channel}" data-client-id="${crypto.randomUUID()}"><div class="field"><label for="special-message">${isBroadcast?'Meddelande till alla':'Ditt förslag'}</label><textarea id="special-message" name="message" required maxlength="4000" rows="4"></textarea></div>${formFooter(isBroadcast?'Skicka till gruppen':'Skicka förslag')}</form>${inbox}</section>`;
 }else if(peer){const chat=await api('/messages/thread/'+peer+(before?'?before='+encodeURIComponent(before):'')),canSend=d.members.some(m=>m.id===peer);if(!document.hidden&&chat.messages.length){const read=await api('/messages/read',{method:'POST',body:{peerId:peer,throughId:chat.messages.at(-1).id}});messageUnread=read.unread;const thread=d.threads.find(t=>t.id===peer);if(thread)thread.unread=0;}
 conversation=`<section class="card message-conversation" aria-labelledby="message-peer"><h3 id="message-peer">${esc(chat.peer.name)}</h3><div class="inline-actions"><button type="button" class="button button-outline button-small" id="refresh-messages">Uppdatera</button>${chat.hasOlder?`<a class="text-link" href="#/mina-sidor/meddelanden?to=${peer}&before=${chat.messages[0].id}">Äldre meddelanden</a>`:''}${before?`<a class="text-link" href="#/mina-sidor/meddelanden?to=${peer}">Senaste meddelandena</a>`:''}</div><div id="message-list" data-peer="${peer}" data-paged="${before?'true':'false'}" role="log" aria-live="polite" aria-label="Konversation">${messageItems(chat.messages)}</div>${canSend?`<form id="message-form" data-peer="${peer}" data-client-id="${crypto.randomUUID()}"><div class="field"><label for="message-text">Ditt meddelande</label><textarea id="message-text" name="message" required maxlength="4000" rows="4" placeholder="Skriv till exempel om en match, domarkollega eller samåkning…"></textarea></div>${formFooter('Skicka meddelande')}</form>`:'<p>Medlemmen har inget aktivt konto just nu. Du kan läsa tidigare meddelanden.</p>'}</section>`;
 }
 return `<h2>Meddelanden</h2><p>Skriv till andra VDK-medlemmar om matcher, samåkning eller annat. Meddelandena visas för dig och mottagaren.</p><div class="card"><form id="message-recipient"><div class="field"><label for="message-member">Skriv till en medlem</label><select id="message-member" name="to" required><option value="">Välj mottagare</option><option value="suggestions" ${channel==='suggestions'?'selected':''}>Lämna förslag</option>${user.roles.includes('ADMIN')?`${Object.entries(broadcastGroups).map(([group,label])=>`<option value="${group}" ${channel===group?'selected':''}>${esc(label)}</option>`).join('')}`:''}${d.members.map(m=>`<option value="${m.id}" ${m.id===peer?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><button type="submit" class="button button-small">Öppna konversation</button></form><label class="check-label" style="margin-top:1rem"><input id="message-email" type="checkbox" ${d.emailEnabled?'checked':''}><span>Mejla mig när jag får meddelanden<small>Från konto@vdk.nu. Aviseringar samlas, högst en per 15 minuter.</small></span></label></div><div class="message-layout"><aside class="card"><h3>Inkorg</h3>${user.roles.includes('ADMIN')?'<a class="message-thread" href="#/mina-sidor/meddelanden?to=suggestions"><strong>Förslagsinkorg</strong><p>Förslag från medlemmarna · Endast admin</p></a>':''}${d.threads.length?d.threads.map(t=>`<a class="message-thread ${t.id===peer?'active':''}" href="#/mina-sidor/meddelanden?to=${t.id}"><strong>${esc(t.name)}</strong>${t.unread?` <span class="badge badge-yellow">${t.unread} olästa</span>`:''}<p>${esc(t.preview.slice(0,100))}</p><small>${esc(new Date(t.created_at).toLocaleDateString('sv-SE'))}</small></a>`).join(''):'<p>Du har inga konversationer ännu.</p>'}</aside>${conversation||'<div class="card"><p>Välj en medlem eller öppna en konversation från inkorgen.</p></div>'}</div>`;
}
async function refreshMessageConversation(){const list=document.querySelector('#message-list');if(!list||list.dataset.paged==='true'||document.hidden)return;const epoch=pageEpoch,peer=Number(list.dataset.peer);const chat=await api('/messages/thread/'+peer);if(epoch!==pageEpoch)return;const oldIds=list.dataset.latest||'',latest=String(chat.messages.at(-1)?.id||'');if(latest!==oldIds){list.innerHTML=messageItems(chat.messages);list.dataset.latest=latest;}if(chat.messages.length)await api('/messages/read',{method:'POST',body:{peerId:peer,throughId:chat.messages.at(-1).id}});}

async function matchCommentsView(){
 const q=new URLSearchParams(location.hash.split('?')[1]||''),d=await api('/commented-matches?'+q),season=q.get('season')||'all',competition=q.get('competition')||'';
 const fields=statisticsSelect('Säsong','season',[{id:'all',name:'Alla säsonger'},...statisticsSeasons.map(s=>({id:s,name:s}))],season,null,'comments')+statisticsSelect('Serie','competition',d.competitions.map(name=>({id:name,name})),competition,'Alla serier','comments');
 const pageLink=page=>'#/mina-sidor/kommentarer?'+new URLSearchParams({...Object.fromEntries(q),page:String(page)});
 return `<h2>Matcher med kommentar</h2><p>Ta del av erfarenheter från VDK-medlemmarnas dömda matcher. Alla serier i matchunderlaget visas från början.</p><form id="comments-search" class="card"><div class="content-grid">${fields}<div class="field"><label for="comments-search-text">Lag, domare eller kommentarstext</label><input type="search" id="comments-search-text" name="search" maxlength="200" value="${esc(q.get('search')||'')}"></div></div><button type="submit" class="button">Visa matcher med kommentarer</button></form><h3 id="comments-results" tabindex="-1">${d.total} matcher med kommentarer</h3>${d.matches.length?d.matches.map(m=>`<article class="card" style="margin-bottom:1rem;overflow-wrap:anywhere"><span class="badge">${esc(m.season)} · ${esc(m.competition_name)}</span><h3>${esc(m.home)} – ${esc(m.away)}</h3><p>${date(m.starts_at)} · ${m.comment_count} kommentarer</p><a class="button button-outline button-small" href="#/mina-sidor/matchkommentar?id=${m.id}">Läs kommentarer</a></article>`).join(''):'<p>Inga matcher med kommentarer i urvalet ännu. Öppna en match i Mina matcher för att skriva den första.</p>'}<div class="inline-actions">${d.page>1?`<a class="button button-outline" href="${esc(pageLink(d.page-1))}">Föregående</a>`:''}${d.page<d.pages?`<a class="button button-outline" href="${esc(pageLink(d.page+1))}">Nästa</a>`:''}</div>`;
}
async function matchCommentView(){
 const id=Number(new URLSearchParams(location.hash.split('?')[1]||'').get('id'));if(!Number.isSafeInteger(id)||id<1)throw Error('Välj en match.');const d=await api('/matches/'+id+'/comments'),mine=d.comments.find(c=>c.user_id===user.id);
 return `<h2>${esc(d.match.home)} – ${esc(d.match.away)}</h2><p>${date(d.match.starts_at)} · ${esc(d.match.season)} · ${esc(d.match.competition_name)}</p><div class="inline-actions"><a class="text-link" href="#/mina-sidor/matcher?season=${encodeURIComponent(d.match.season)}">Mina matcher</a><a class="text-link" href="#/mina-sidor/kommentarer">Matcher med kommentar</a></div><h3>Matchkommentarer</h3><p>Kommentarerna delas med inloggade VDK-medlemmar och visas med ditt namn.</p>${d.comments.map(c=>`<article class="card" style="margin-bottom:1rem;overflow-wrap:anywhere"><strong>${esc(c.name)}</strong><p style="white-space:pre-wrap;margin-top:1rem">${esc(c.body)}</p><small>${esc(new Date(c.updated_at).toLocaleString('sv-SE',{timeZone:'Europe/Stockholm'}))}${c.updated_at!==c.created_at?' · Uppdaterad':''}</small>${c.user_id===user.id||user.roles.includes('ADMIN')?`<div class="inline-actions"><button class="button button-quiet button-small delete-match-comment" data-match="${id}" data-comment="${c.id}">Ta bort ${c.user_id===user.id?'min kommentar':'kommentaren'}</button></div>`:''}</article>`).join('')||'<p>Ingen har kommenterat matchen ännu.</p>'}${d.canComment?`<div class="card"><form id="match-comment-form" data-match="${id}"><div class="field"><label for="match-comment-text">${mine?'Redigera din kommentar':'Din kommentar till matchen'}</label><textarea name="comment" id="match-comment-text" required maxlength="4000" rows="6">${esc(mine?.body||'')}</textarea></div>${formFooter(mine?'Spara ändringen':'Publicera kommentar')}</form></div>`:'<p>Du kan läsa kommentarerna. Bara domare som själva dömt matchen kan skriva en kommentar.</p>'}`;
}

function controlRoom(d){
 const link=(path,label)=>`<a class="text-link" href="#/mina-sidor/${path}">${label} →</a>`;
 const ibis=`<aside class="control-ibis"><h2>Matchuppdrag och tillsättningar</h2><p>VDK visar inte kommande matchuppdrag. Kontrollera alltid dina officiella tillsättningar och matchuppgifter i iBIS och förbundets officiella kanaler.</p></aside>`;
 if(!d.access)return `<div class="control-room"><section class="card control-status"><p class="eyebrow">Medlemsstatus</p><h2>Ditt medlemskap är inte aktivt ännu</h2><p>VDK har ännu inte registrerat och godkänt din medlemsbetalning för säsongen ${esc(d.season)}. Medlemsfunktionerna är låsta tills medlemskapet är aktivt.</p>${d.membership?`<p>${d.membership.paid?'Betalningen är registrerad. Kontrollera medlemsstatus med VDK.':`Avgift: ${money(d.membership.amount)} · Swish: ${esc(d.swishNumber||'Kontakta VDK')}<br>Meddelande: ${esc(d.membership.payment_reference)}`}</p>`:'<p>Du saknar ett medlemskap för aktuell säsong. Kontakta VDK.</p>'}${link('medlemskap','Se mitt medlemskap')}</section>${ibis}</div>`;
 const fresh=d.coachings.filter(c=>!c.viewed_at);
 const max=Math.max(1,...d.months.map(m=>m.count));
 return `<div class="control-room"><section class="card control-todo"><p class="eyebrow">Att göra</p><h2>${fresh.length?'Nytt för dig':'✓ Allt är klart'}</h2>${fresh.length?`<p>${fresh.length} videocoachningar att ta del av.</p>${link('video','Öppna videocoachning')}`:'<p>Inga nya coachningar kräver din uppmärksamhet.</p>'}<p class="control-membership">Medlemsfunktionerna är öppna · ${esc(d.season)} · ${link('medlemskap','Mitt medlemskap')}</p></section>
 <div class="control-metrics">${[['Dömda matcher',d.counts.matches,'matcher','Verifierade spelade matcher denna säsong.'],['Utvisningar',d.counts.penalties,'statistik','Registrerade händelser i dina matcher.'],[d.fee.status==='partial'?'Arvode – känt underlag':'Beräknat arvode',d.fee.amount===null?'Data saknas':money(d.fee.amount),'arvode','Exklusive reseersättning och eventuella övriga ersättningar.'],['Videocoachningar',d.counts.coachings,'video',fresh.length?fresh.length+' nya att läsa':'Tillgängliga publicerade coachningar.']].map(([title,value,path,detail])=>`<a class="card control-metric" href="${path==='arvode'?'#/mina-sidor/arvode':'#/mina-sidor/'+path}"><span class="eyebrow">${title}</span><strong class="control-value ${typeof value==='string'?'control-value-text':''}">${value}</strong><p>${detail}</p></a>`).join('')}</div>
 ${fresh.length?`<section class="card control-new"><p class="eyebrow">Ny videocoachning</p><h2>${esc(fresh[0].home)} – ${esc(fresh[0].away)}</h2><p>${date(fresh[0].starts_at)} · ${esc(fresh[0].competition_name)}<br>${fresh[0].clip_count} situationer analyserade · ⭐ 2 styrkor · 💭 1 utvecklingsfokus · Coach: ${esc(fresh[0].coach_name)}</p>${link('video?id='+fresh[0].id,'Öppna coachning')}</section>`:''}
 <div class="control-grid"><section class="card"><p class="eyebrow">Min säsong</p><h2>${d.counts.matches} dömda matcher</h2><p>${d.counts.colleagues} olika domarkollegor</p><h3>Matcher per månad</h3>${d.months.length?`<ul class="control-months">${d.months.map(m=>`<li><span>${esc(new Date(m.month+'-15').toLocaleDateString('sv-SE',{month:'long',year:'numeric'}))}</span><span class="control-bar" aria-hidden="true" style="--bar:${m.count/max*100}%"></span><strong>${m.count}</strong></li>`).join('')}</ul>`:'<p>Inga verifierade spelade matcher denna säsong ännu.</p>'}${link('matcher','Se mina matcher')}</section>
 <section class="card"><p class="eyebrow">Mina utvisningar</p><h2>Vanligaste utvisningstyperna</h2>${d.topPenalties.length?`<ol class="control-penalties">${d.topPenalties.map(p=>`<li><span>${esc(p.category)}${p.code?` <small>(${esc(p.code)})</small>`:''}</span><strong>${p.count}</strong></li>`).join('')}</ol>`:'<p>Inga registrerade utvisningar i säsongens matcher.</p>'}<p>Totalt: <strong>${d.counts.penalties}</strong> · Snitt: <strong>${d.average.toLocaleString('sv-SE',{maximumFractionDigits:2})}</strong> utvisningar / match</p><p class="control-note">Matchprotokollet visar domarparets händelser, inte vilken domare som fattade beslutet.</p>${link('statistik?season='+encodeURIComponent(d.season),'Se hela min statistik')}</section>
 <section class="card" id="control-fees"><p class="eyebrow">Mitt domararvode</p><h2>${d.fee.amount===null?'Arvodesunderlag saknas för dina matcher':money(d.fee.amount)}</h2><p>${d.fee.status==='partial'?'Delsumma för identifierade nivåer. ':''}${d.fee.pricedMatches} av ${d.counts.matches} matcher ingår. ${d.fee.unpricedMatches?d.fee.unpricedMatches+' matcher saknar säker nivåkoppling.':''}</p><p>${esc(d.fee.source)} · Exklusive reseersättning och eventuella övriga ersättningar.</p>${d.fee.months.length?`<ul>${d.fee.months.map(m=>`<li>${esc(m.month)}: ${money(m.amount)}</li>`).join('')}</ul>`:''}<details><summary>Visa arvodesunderlag</summary><p>${esc(d.fee.reason)} Beloppen är beräknade arvoden, inte bekräftade utbetalningar.</p><div class="control-latest">${d.fee.items.map(m=>`<div class="control-fee-row"><span>${date(m.starts_at)} · ${esc(m.competition_name)}</span><strong>${esc(m.home)} – ${esc(m.away)}</strong><span>${m.amount===null?'Data saknas – nivå behöver kontrolleras':money(m.amount)}</span></div>`).join('')||'<p>Inga spelade matcher i underlaget ännu.</p>'}</div></details></section>
 <section class="card"><p class="eyebrow">Min utveckling</p><h2>${d.developmentFocus?'Steg '+(d.developmentFocus.wish_step+1)+' – '+esc(developmentSteps[d.developmentFocus.wish_step]?.title||'Utveckling'):'Hitta ditt nästa utvecklingsfokus'}</h2><p>Utforska VDK:s utvecklingstrappa tillsammans med din coach. ${d.developmentFocus?'Senaste coachningen kopplar ditt fokus till '+esc(developmentSteps[d.developmentFocus.wish_step]?.title||'utvecklingstrappan')+'.':'Inget individuellt steg är registrerat ännu.'}</p><p>${d.developmentFocus?esc(d.developmentFocus.wish):''}</p><a class="text-link" href="#/kunskapsnivaer${d.developmentFocus?'?step='+d.developmentFocus.wish_step:''}">Se min utveckling →</a><p class="control-note">Ett pedagogiskt utvecklingsverktyg, inte officiell ranking eller behörighet.</p></section></div>
 <details class="card statistics-fold"><summary>Din spelade säsong – senaste matcher</summary><div class="statistics-fold-body">${d.latestMatches.length?`<div class="control-latest">${d.latestMatches.map(m=>`<a href="#/mina-sidor/matchkommentar?id=${m.id}"><span>${date(m.starts_at)} · ${esc(m.competition_name)}</span><strong>${esc(m.home)} – ${esc(m.away)}</strong><span>Domarkollega: ${esc(m.colleague||'Ingen registrerad')} · ${m.penalty_count} utvisningar</span></a>`).join('')}</div>`:'<p>Inga verifierade spelade matcher denna säsong ännu.</p>'}${link('matcher','Alla mina matcher')}</div></details>
 ${d.notifications.length?`<details class="card"><summary>VDK-information och tidigare notiser</summary>${d.notifications.map(n=>`<p>${esc(n.message)}</p>`).join('')}</details>`:''}${ibis}</div>`;
}

function portalShell(tab,body){return `<section class="page container"><div class="portal-head"><div><p class="eyebrow">Mina sidor</p><h1>${isSupport()?'Hej '+esc(user.name.split(' ')[0])+'.':tab?'Hej '+esc(user.name.split(' ')[0])+'.':'Mitt kontrollrum'}</h1><p>${isSupport()?'Välkommen till Mina sidor · Stödmedlem':tab?'Ditt domarcentrum i Värmland.':'Hej '+esc(user.name.split(' ')[0])+' · Säsongen '+esc(user.season)}</p></div><div>${user.roles.includes('ADMIN')?'<a class="button button-outline button-small" href="#/admin">Administration</a> ':''}<button class="button button-quiet button-small" id="logout">Logga ut</button></div></div>${isSupport()?'<a class="text-link" href="#/mina-sidor">Till min startsida</a>':`<nav class="portal-navigation" aria-label="Mina sidor"><a class="portal-home ${tab?'':'active'}" href="#/mina-sidor" ${tab?'':'aria-current="page"'}>Mitt kontrollrum</a><a class="button portal-rules" href="/member-rules/">Regelgenerator</a><div class="portal-menu-wrap"><button type="button" class="portal-menu-button ${tab?'active':''}" data-portal-menu aria-expanded="false" aria-controls="portal-menu"><span aria-hidden="true">☰</span> <span>${esc(tab?(portalTabs.find(([p])=>p===tab)?.[1]||(tab==='coach'?'Coachuppdrag':'Meny')):'Meny')}</span><span aria-hidden="true">⌄</span></button><div class="portal-menu" id="portal-menu" hidden>${[...portalTabs.filter(([p])=>p),...(user.roles.includes('VIDEO_COACH')?[['coach','Coachuppdrag']]:[])].map(([p,t])=>`<a href="#/mina-sidor/${p}" ${p===tab?'aria-current="page"':''}>${t}${p==='meddelanden'?` <span data-unread-badge class="badge badge-yellow" ${messageUnread?'':'hidden'}>${messageUnread||''}</span>`:''}</a>`).join('')}</div></div></nav>`}${body}</section>`;}
async function portal(tab){try{user=(await api('/me')).user;}catch{user=null;updateAccountNavigation();return login();}let body='';if(isSupport()&&!['profil','dokument','regler','medlemsprofil'].includes(tab))return supportHome();
  if(!user.roles.includes('ADMIN')){const {memberships}=await api('/membership');const active=memberships.some(m=>m.season===user.season&&m.status==='active'&&m.paid&&m.category!=='business');if(!active&&!['','medlemskap','profil'].includes(tab))return portalShell(tab,notice('<strong>Tyvärr har du inte tillgång till den här tjänsten.</strong><br>'+(memberships.some(m=>m.season===user.season&&m.status==='expired')?'Ditt medlemskap är avslutat. Kontakta VDK för att återaktivera det.':memberships.some(m=>m.season===user.season&&m.paid)?'Din betalning är registrerad, men medlemskapet väntar på godkännande från VDK.':'Tjänsten är för betalande medlemmar. Betala medlemsavgiften för att få tillgång. Åtkomsten öppnas när VDK har registrerat och godkänt din betalning.'),'error')+'<a class="button" href="#/mina-sidor/medlemskap">Se mitt medlemskap</a>');}
  if(tab==='regler'){try{await api('/rules/access');body=`<div class="card"><h2>Regelgenerator – fullversion</h2><p>Träna på situationer, gör prov och använd hela regelbanken.</p><a class="button" href="${location.hostname==='vdk.nu'||location.hostname==='www.vdk.nu'?'https://vdk-members.soren-johansson-7.workers.dev':''}/member-rules/">Öppna fullversionen</a><p><a class="text-link" href="#/kunskapsnivaer">VDK:s kunskapsnivåer</a></p></div>`;}catch(error){body=notice(esc(error.message),'error')+'<a class="button" href="#/regel-demo">Prova gratis demo</a>';}}
  else if(tab==='arvode'){body=controlRoom(await api('/dashboard'));setTimeout(()=>document.querySelector('#control-fees')?.scrollIntoView({block:'start'}),0);}
  else if(tab==='profil'){body=await profileView();}
  else if(tab==='medlemsprofil'){body=await sharedProfileView();}
  else if(tab==='sok-matcher'){body=await matchSearchView();}
  else if(tab==='kommentarer'){body=await matchCommentsView();}
  else if(tab==='matchkommentar'){body=await matchCommentView();}
  else if(tab==='medlemmar'){const {members}=await api('/members');body=memberDirectoryMarkup(members);}
  else if(tab==='dokument'){body=await documentsView();}
  else if(tab==='meddelanden'){body=await messagesView();}
  else if(tab==='varmland'){body=await regionalStats();}
  else if(tab==='matcher'){body=await personalMatches();}
  else if(tab==='statistik'||tab==='forbund'){body=await personalStats();}
  else if(tab==='aterbud'){body=await availabilityView();}
  else if(tab==='domartavlan'){await api('/board/access');body='<h2>VDK Domartavla</h2><p>Visa positioner och rörelser tillsammans med din domarkollega. Tavlan sparas inte när du lämnar sidan.</p><div id="standalone-board"></div>';}
  else if(tab==='video'){body=await memberCoachingHistory();}
  else if(tab==='medlemskap'){const {memberships,coachApplication}=await api('/membership');body=`<div class="content-grid"><div class="card"><h2>Mitt medlemskap</h2><p>${esc(user.name)}<br>${esc(user.email)}</p><div class="table-wrap"><table><thead><tr><th>Säsong</th><th>Status</th><th>Betalning</th></tr></thead><tbody>${memberships.map(x=>`<tr><td>${esc(x.season)}</td><td>${esc(statusLabel(x.status))}</td><td>${x.paid?'Bekräftad':'Ej bekräftad'}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Bli videocoach</h2>${user.roles.includes('VIDEO_COACH')?'<p>Du är godkänd videocoach. Dina uppdrag finns i coachverktyget.</p>':coachApplication?`<p>Din ansökan: <span class="badge">${esc(statusLabel(coachApplication.status))}</span></p>`:`<p>Vill du bidra till domarutvecklingen i seniorinnebandyn? Beskriv din erfarenhet och varför du vill bli videocoach.</p><form id="coach-application"><div class="field"><label for="motivation">Din erfarenhet och motivation</label><textarea name="motivation" id="motivation" required maxlength="3000"></textarea></div>${formFooter('Ansök om att bli videocoach')}</form>`}</div></div>`;}
  else if(tab==='coach'&&user.roles.includes('VIDEO_COACH')){body=await coachAssignments();}
  else {body=controlRoom(await api('/dashboard'));}
  try{messageUnread=(await api('/messages/unread')).unread;}catch{messageUnread=0;}
  body+='<div class="inline-actions"><a class="text-link" href="#/mina-sidor/regler">Regelgenerator</a><a class="text-link" href="#/kunskapsnivaer">Kunskapsnivåer</a></div>';return portalShell(tab,body);
}
function statusLabel(status){return ({pending:'Väntar på godkännande',approved:'Godkänd',active:'Aktivt',rejected:'Avslagen',expired:'Avslutat',draft:'Utkast',published:'Publicerad'})[status]||status;}
function matchTable(matches,{regional=false}={}){const refs=regional?'Domare':'Domarkollega';return `<div class="card table-wrap statistics-table-wrap"><table class="statistics-table"><caption class="sr-only">Matcher i urvalet</caption><thead><tr><th scope="col">Datum</th><th scope="col">Match</th><th scope="col">${refs}</th><th scope="col">Säsong / serie</th><th scope="col">Utvisningar</th><th scope="col">Källa</th><th scope="col">Kommentarer</th></tr></thead><tbody>${matches.map(m=>`<tr><td data-label="Datum">${date(m.starts_at)}</td><td data-label="Match">${esc(m.home)} – ${esc(m.away)}</td><td data-label="${refs}">${esc(m.colleague||'Ej angiven')}</td><td data-label="Säsong / serie">${esc(m.season)}<br><small>${esc(m.competition_name||'')}${m.competition_scope==='federal'?' · Förbundsserie':''}</small></td><td data-label="Utvisningar">${m.penalty_count??'–'}</td><td data-label="Källa"><a class="text-link" href="${esc(m.source_url)}" target="_blank" rel="noopener">Matchprotokoll</a></td><td data-label="Kommentarer"><a class="text-link" href="#/mina-sidor/matchkommentar?id=${m.id}">${m.comment_count?m.comment_count+' kommentarer':'Läs / kommentera'}</a></td></tr>`).join('')}</tbody></table></div>`;}
function colleagueTable(rows,season,team='',against=false,competition='',code='',scope='all'){return rows.length?`<div class="card table-wrap statistics-table-wrap"><table class="statistics-table"><caption class="sr-only">Domarkollegor i urvalet</caption><thead><tr><th scope="col">Domarkollega</th><th scope="col">Matcher</th><th scope="col">Utvisningar tillsammans</th></tr></thead><tbody>${rows.map(r=>`<tr><td data-label="Domarkollega">${r.colleague?`<a class="text-link" href="#/mina-sidor/statistik?${esc(new URLSearchParams({season,colleague:r.colleague,team,competition,code,scope,against:String(against)}))}">${esc(r.colleague)}</a>`:'Ej angiven'}</td><td data-label="Matcher">${r.matches}</td><td data-label="Utvisningar tillsammans">${r.penalties}</td></tr>`).join('')}</tbody></table></div>`:empty('Inga domarkollegor registrerade.','Kollegorna visas när dina matcher har importerats.');}
function statsView(data){return data.matches?`<div class="season-summary"><div><strong>${data.matches}</strong><span>Unika matcher</span></div><div><strong>${data.penalties}</strong><span>Utvisningar</span></div><div><strong>${Number(data.penaltiesPerMatch||0).toLocaleString('sv-SE',{maximumFractionDigits:2})}</strong><span>Utvisningar per match</span></div></div>${data.categories.length?`<details class="statistics-fold"><summary>Utvisningar per typ</summary><div class="table-wrap statistics-table-wrap"><table class="statistics-table"><caption class="sr-only">Utvisningar per kategori</caption><thead><tr><th scope="col">Kod / kategori</th><th scope="col">Antal händelser</th><th scope="col">Andel</th></tr></thead><tbody>${data.categories.map(c=>`<tr><td data-label="Kod / kategori">${c.code?`${esc(c.code)} · `:''}${esc(c.category)}</td><td data-label="Antal händelser">${c.count}</td><td data-label="Andel">${data.penalties?Math.round(100*c.count/data.penalties):0} %</td></tr>`).join('')}</tbody></table></div></details>`:'<p>Inga utvisningar i urvalet.</p>'}`:empty('Inga matcher i urvalet.','Välj en annan säsong, ett annat lag eller en annan domare.');}

function coachingMeta(c){return `<div class="coaching-meta"><span>${date(c.starts_at)} · ${esc(c.season)}</span><span>${esc(c.competition_name)}</span><span>Domare: ${esc(c.member_name)} · Domarkollega: ${esc(c.colleague||'Ingen registrerad')}</span><span>Coach: ${esc(c.coach_name)}</span><span class="badge">${c.status==='published'?'Publicerad':'Utkast'}</span></div>${c.video_url?`<p><a class="text-link" href="${esc(c.video_url)}" target="_blank" rel="noopener">Öppna extern videokälla →</a></p>`:''}`;}
function protocolText(title,value){return `<section class="coaching-text"><h3>${title}</h3><p>${esc(value||'Uppgift saknas i det äldre protokollet.')}</p></section>`;}
function illustrationMarkup(clip,editable=false){return `${clip.board?`<div class="board-preview">${boardSVG(clip.board)}</div><button type="button" class="button button-outline button-small view-board" data-board="${esc(JSON.stringify(clip.board))}">Öppna i stort format</button>`:''}${editable?`<div class="inline-actions"><button type="button" class="button button-outline button-small edit-board" data-clip="${clip.id}" data-board="${esc(JSON.stringify(clip.board||emptyBoard()))}">${clip.board?'Redigera tavla':'+ Illustrera situation'}</button>${clip.board?`<button type="button" class="button button-quiet button-small delete-board" data-clip="${clip.id}">Ta bort tavla</button>`:''}</div>`:''}`;}
function bindBoardViews(){const root=document.querySelector('#standalone-board');if(root)mountBoard(root);document.querySelectorAll('.view-board').forEach(b=>b.onclick=()=>openBoard({data:JSON.parse(b.dataset.board),mode:'view'}));}
function coachingView(c){return `<article class="card coaching-protocol"><p class="eyebrow">Videocoachning</p><h2>${esc(c.home)} – ${esc(c.away)}</h2>${coachingMeta(c)}<h2>Situationer</h2><ol class="coaching-situations">${c.clips.map(x=>`<li><span class="badge badge-yellow">${x.period?'Period '+x.period+' · ': 'Äldre videotid · '}${time(x.start_seconds)}</span><p>${esc(x.comment)}</p>${illustrationMarkup(x)}</li>`).join('')}</ol>${protocolText('Helhetsbild',c.overview)}<h2>Two Stars and a Wish</h2><div class="coaching-stars">${protocolText('⭐ Star 1 – Det här gjorde du bra',c.star1)}${protocolText('⭐ Star 2 – Det här ska du fortsätta med',c.star2)}${protocolText('💭 Wish – Ditt nästa utvecklingsfokus',c.wish)}</div>${c.wish_step!==null&&developmentSteps[c.wish_step]?`<section class="coaching-text"><h3>Utvecklingsfokus</h3><p>Steg ${c.wish_step+1} – ${esc(developmentSteps[c.wish_step].title)}</p><a class="text-link" href="#/kunskapsnivaer?step=${c.wish_step}">Läs mer om detta utvecklingsområde →</a><p>Pedagogiskt utvecklingsverktyg, inte officiell ranking.</p></section>`:''}</article>`;}
async function memberCoachingHistory(){const id=Number(new URLSearchParams(location.hash.split('?')[1]).get('id'));if(id){const {coaching:c}=await api('/coachings/'+id);await api('/coachings/viewed',{method:'POST',body:{id}});return `<p><a class="text-link" href="#/mina-sidor/video">← Mina videocoachningar</a> · <span class="badge">Läst</span></p>${coachingView(c)}`;}const {coachings}=await api('/coachings');const seasons=[...new Set(coachings.map(c=>c.season))].sort().reverse();return `<h2>Mina videocoachningar</h2><p>Din personliga utvecklingshistorik. Öppna ett protokoll för att läsa coachens återkoppling.</p>${seasons.map(season=>`<h3>${esc(season)}</h3><div class="coaching-history">${coachings.filter(c=>c.season===season).map(c=>`<a class="card" href="#/mina-sidor/video?id=${c.id}"><span class="badge ${c.viewed_at?'':'badge-yellow'}">${c.viewed_at?'Läst':'Ny'}</span><h3>${esc(c.home)} – ${esc(c.away)}</h3><p>${date(c.starts_at)} · ${esc(c.competition_name)}<br>Coach: ${esc(c.coach_name)} · ${c.clips.length} situationer</p><p>Wish: ${esc(c.wish_step!==null&&developmentSteps[c.wish_step]?developmentSteps[c.wish_step].title:c.wish||'Inget utvecklingsområde registrerat')}</p><span class="text-link">Öppna coachning →</span></a>`).join('')}</div>`).join('')||empty('Inga publicerade coachningar ännu.','När en coachning publiceras visas den här och i ditt kontrollrum.')}`;}
function coachingDraftFields(c){return ['overview','star1','star2','wish'].map((key,i)=>`<div class="field"><label for="protocol-${key}">${['Helhetsbild','⭐ Star 1 – Det här gjorde du bra','⭐ Star 2 – Det här ska du fortsätta med','💭 Wish – Ditt nästa utvecklingsfokus'][i]}</label><textarea id="protocol-${key}" name="${key}" maxlength="${i?5000:10000}" rows="${i?4:7}">${esc(c[key]||'')}</textarea></div>`).join('');}
async function coachAssignments(){const id=Number(new URLSearchParams(location.hash.split('?')[1]).get('id'));if(id){const {coaching:c}=await api('/coach/work/'+id);if(c.status==='published')return `<p><a class="text-link" href="#/mina-sidor/coach">← Mina coachuppdrag</a></p>${coachingView(c)}`;return `<div class="coaching-editor" data-coaching="${c.id}" data-revision="${c.revision}"><a class="text-link" href="#/mina-sidor/coach">← Mina coachuppdrag</a><p class="eyebrow">Videocoachning · Utkast</p><h2>${esc(c.home)} – ${esc(c.away)}</h2>${coachingMeta(c)}<p>Protokollet är privat tills du publicerar det. Video lagras inte hos VDK.</p><section class="card"><h2>Situationer</h2><p>Sorteras efter period och tid. Du kan också flytta dem manuellt.</p><ol class="coaching-situations">${c.clips.map((x,i)=>`<li data-situation="${x.id}"><strong>${x.period?'Period '+x.period:'Period saknas'} · ${time(x.start_seconds)}</strong><p>${esc(x.comment)}</p>${illustrationMarkup(x,true)}<div class="inline-actions"><button type="button" class="button button-outline button-small edit-situation" data-id="${x.id}" data-period="${x.period||1}" data-seconds="${x.start_seconds}">Redigera</button><button type="button" class="button button-quiet button-small delete-situation" data-id="${x.id}">Ta bort</button><button type="button" class="button button-quiet button-small move-situation" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Flytta situation ${i+1} upp">↑</button><button type="button" class="button button-quiet button-small move-situation" data-index="${i}" data-direction="1" ${i===c.clips.length-1?'disabled':''} aria-label="Flytta situation ${i+1} ner">↓</button></div></li>`).join('')}</ol><button type="button" class="button button-outline" id="new-situation">+ Lägg till situation</button><form id="situation-form" hidden><input type="hidden" name="clipId" value=""><div class="content-grid"><div class="field"><label for="situation-period">Period</label><select id="situation-period" name="period">${[1,2,3,4,5].map(n=>`<option value="${n}">${n}${n===4?' – Förlängning':n===5?' – Straffläggning':''}</option>`).join('')}</select></div><div class="field"><label for="situation-time">Matchtid (mm:ss)</label><input id="situation-time" name="time" required pattern="[0-5]?[0-9]:[0-5][0-9]" placeholder="12:34"></div></div><div class="field"><label for="situation-comment">Kommentar</label><textarea id="situation-comment" name="comment" required maxlength="5000" rows="4"></textarea></div>${formFooter('Spara situation')}<button type="button" class="button button-outline" id="illustrate-new-situation">+ Illustrera situation</button></form></section><section class="card"><h2>Helhetsbild och avslutning</h2><form id="protocol-form">${coachingDraftFields(c)}<div class="field"><label for="wish-step">Kopplat utvecklingsområde (frivilligt)</label><select name="wishStep" id="wish-step"><option value="">Inget valt</option>${developmentSteps.map((step,i)=>`<option value="${i}" ${c.wish_step===i?'selected':''}>Steg ${i+1} – ${esc(step.title)}</option>`).join('')}</select></div>${formFooter('Spara utkast')}</form><p>Före publicering behövs minst en situation, helhetsbild, två styrkor och en Wish.</p><button type="button" class="button" id="publish-protocol">Publicera videocoachning</button><p id="protocol-status" role="status"></p></section></div>`;}const {coachings}=await api('/coach/work');const started=c=>c.clips.length||c.overview||c.star1||c.star2||c.wish;return `<h2>Mina coachuppdrag</h2><p>Titta på matchen i dess externa källa och ge domaren konkret återkoppling.</p>${[['Att göra',c=>c.status==='draft'&&!started(c)],['Påbörjade',c=>c.status==='draft'&&started(c)],['Publicerade',c=>c.status==='published']].map(([label,filter])=>`<section class="coaching-group"><h3>${label}</h3><div class="coaching-history">${coachings.filter(filter).map(c=>`<a class="card" href="#/mina-sidor/coach?id=${c.id}"><h3>${esc(c.home)} – ${esc(c.away)}</h3><p>${date(c.starts_at)} · ${esc(c.competition_name)}<br>Domare: ${esc(c.member_name)}<br>Kollega: ${esc(c.colleague||'Ingen registrerad')}</p><span class="text-link">${c.status==='draft'?'Öppna utkast':'Läs protokoll'} →</span></a>`).join('')||'<p>Inga uppdrag i den här gruppen.</p>'}</div></section>`).join('')}`;}

function bindCoaching(){
 const assignment=document.querySelector('#assignment-form');if(assignment){const season=assignment.querySelector('#coaching-season'),match=assignment.querySelector('#matchId'),members=assignment.querySelector('#memberId'),matchOptions=[...match.options].map(o=>o.cloneNode(true)),memberOptions=[...members.options].map(o=>o.cloneNode(true));const updateMembers=()=>{const ids=(match.selectedOptions[0]?.dataset.members||'').split(','),previous=members.value;members.replaceChildren(...memberOptions.filter(o=>ids.includes(o.value)).map(o=>o.cloneNode(true)));if([...members.options].some(o=>o.value===previous))members.value=previous;members.disabled=!members.options.length;assignment.querySelector('button[type="submit"]').disabled=!members.options.length;};const updateSeason=()=>{match.replaceChildren(...matchOptions.filter(o=>o.dataset.season===season.value).map(o=>o.cloneNode(true)));if(!match.options.length)match.add(new Option('Inga verifierade matcher för säsongen',''));match.disabled=!match.value;assignment.querySelector('#coaching-season-note').textContent=season.value===season.dataset.current?'Videocoachning för aktuell säsong '+season.value+'.':'Äldre säsong '+season.value+' – coachning av äldre matcher görs på domarens begäran.';updateMembers();};season.addEventListener('change',updateSeason);match.addEventListener('change',updateMembers);updateSeason();}

 const editor=document.querySelector('.coaching-editor');if(!editor)return;const form=editor.querySelector('#protocol-form'),situation=editor.querySelector('#situation-form'),id=Number(editor.dataset.coaching),status=editor.querySelector('#protocol-status');let busy=false;
 const save=async()=>{const data=Object.fromEntries(new FormData(form));data.wishStep=data.wishStep===''?null:Number(data.wishStep);data.revision=Number(editor.dataset.revision);const saved=await api('/coach/work/'+id+'/save',{method:'POST',body:data});editor.dataset.revision=saved.revision;editor.dataset.dirty='false';status.textContent='Utkastet är sparat. Medlemmen ser det först efter publicering.';return saved;};
 const run=async fn=>{if(busy)return;busy=true;const buttons=[...editor.querySelectorAll('button')];buttons.forEach(b=>{b.dataset.wasDisabled=String(b.disabled);b.disabled=true;});try{await fn();}catch(error){status.textContent=error.message;toast(error.message);}finally{buttons.forEach(b=>b.disabled=b.dataset.wasDisabled==='true');busy=false;}};
 form.addEventListener('input',()=>editor.dataset.dirty='true');form.addEventListener('change',()=>editor.dataset.dirty='true');form.addEventListener('submit',e=>{e.preventDefault();run(save);});
 const show=()=>{situation.hidden=false;situation.querySelector('#situation-comment').focus();};
 editor.querySelector('#new-situation').addEventListener('click',()=>{situation.reset();situation.elements.clipId.value='';show();});
 editor.querySelectorAll('.edit-situation').forEach(b=>b.addEventListener('click',()=>{situation.elements.clipId.value=b.dataset.id;situation.elements.period.value=b.dataset.period;situation.elements.time.value=time(Number(b.dataset.seconds));situation.elements.comment.value=b.closest('[data-situation]').querySelector('p').textContent;show();}));
 const saveSituation=async()=>{const data=Object.fromEntries(new FormData(situation)),[m,s]=data.time.split(':').map(Number);await save();return api('/coach/work/'+id+'/clips'+(data.clipId?'/'+data.clipId:''),{method:'POST',body:{period:Number(data.period),seconds:m*60+s,comment:data.comment,revision:Number(editor.dataset.revision)}});};
 situation.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await saveSituation();toast('Situationen och utkastet är sparade.');await route();});});
 editor.querySelector('#illustrate-new-situation').onclick=()=>{if(!situation.reportValidity())return;run(async()=>{const saved=await saveSituation();await route();document.querySelector('.edit-board[data-clip="'+saved.clipId+'"]')?.click();});};
 editor.querySelectorAll('.edit-board').forEach(b=>b.onclick=()=>run(async()=>{await save();openBoard({data:JSON.parse(b.dataset.board),mode:'edit',onSave:async board=>{const saved=await api('/coach/work/'+id+'/clips/'+b.dataset.clip+'/board',{method:'POST',body:{board,revision:Number(editor.dataset.revision)}});editor.dataset.revision=saved.revision;toast('Domartavlan är sparad i situationen.');await route();}});}));
 editor.querySelectorAll('.delete-board').forEach(b=>b.onclick=()=>run(async()=>{await save();await api('/coach/work/'+id+'/clips/'+b.dataset.clip+'/board',{method:'POST',body:{board:null,revision:Number(editor.dataset.revision)}});await route();}));
 editor.querySelectorAll('.delete-situation').forEach(b=>b.addEventListener('click',()=>{if(!confirm('Ta bort den här situationen?'))return;run(async()=>{await save();await api('/coach/work/'+id+'/clips/'+b.dataset.id+'/delete',{method:'POST',body:{revision:Number(editor.dataset.revision)}});await route();});}));
 editor.querySelectorAll('.move-situation').forEach(b=>b.addEventListener('click',()=>run(async()=>{const ids=[...editor.querySelectorAll('[data-situation]')].map(el=>Number(el.dataset.situation)),i=Number(b.dataset.index),next=i+Number(b.dataset.direction);[ids[i],ids[next]]=[ids[next],ids[i]];await save();await api('/coach/work/'+id+'/order',{method:'POST',body:{ids,revision:Number(editor.dataset.revision)}});await route();})));
 editor.querySelector('#publish-protocol').addEventListener('click',()=>{if(!confirm('När coachningen publiceras blir den tillgänglig för medlemmen på Mina sidor. Publicera?'))return;run(async()=>{await save();await api('/coach/work/'+id+'/publish',{method:'POST',body:{revision:Number(editor.dataset.revision)}});toast('Coachningen är publicerad. Medlemmen har fått en VDK-notis.');await route();});});
}

async function admin(tab){try{user=(await api('/me')).user;}catch{return login();}if(!user.roles.includes('ADMIN'))return page('Åtkomst saknas.','Den här sidan är endast tillgänglig för administratörer.','');const tabs=[['','Medlemmar'],['coacher','Coachansökningar'],['uppdrag','Videouppdrag'],['statistik','VDK-statistik'],['dokument','Dokument']];let body='';
  if(tab==='dokument'){body=await documentsView(true);}
  else if(tab==='coacher'){const {applications}=await api('/admin/coach-applications');body=`<h2>Videocoachansökningar</h2>${applications.length?applications.map(a=>`<div class="card" style="margin-bottom:1rem"><h3>${esc(a.name)}</h3><p>${esc(a.motivation)}</p><span class="badge">${esc(statusLabel(a.status))}</span>${a.status==='pending'?`<div class="inline-actions"><button class="button coach-decision" data-id="${a.id}" data-status="approved">Godkänn</button><button class="button button-outline coach-decision" data-id="${a.id}" data-status="rejected">Avslå</button></div>`:''}</div>`).join(''):empty('Inga coachansökningar.','Ansökningar från medlemmar visas här.')}`;}
  else if(tab==='uppdrag'){const {matches,coaches,members,participants}=await api('/admin/coaching-options');const {coachings}=await api('/admin/coachings');const current=(await loadSettings()).season,seasons=[...new Set([current,...matches.map(m=>m.season)])].sort().reverse();body=`<h2>Videocoachuppdrag · ${esc(current)}</h2>${matches.length&&coaches.length?`<div class="card"><form id="assignment-form"><div class="field"><label for="coaching-season">Säsong</label><select id="coaching-season" data-current="${esc(current)}">${seasons.map(s=>`<option value="${esc(s)}" ${s===current?'selected':''}>${esc(s)}${s===current?' – aktuell säsong':''}</option>`).join('')}</select></div><p id="coaching-season-note" role="status"></p><div class="field"><label for="matchId">Match</label><select id="matchId" name="matchId" required>${matches.map(m=>`<option value="${m.id}" data-season="${esc(m.season)}" data-members="${participants.filter(p=>p.match_id===m.id).map(p=>p.user_id).join(',')}">${esc(m.season)} · ${esc(m.home)} – ${esc(m.away)} · ${esc(m.competition_name)} (${date(m.starts_at)})</option>`).join('')}</select></div><div class="field"><label for="memberId">Domare som coachas</label><select id="memberId" name="memberId" required>${members.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="coachId">Videocoach</label><select id="coachId" name="coachId" required>${coaches.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div>${field('Extern videolänk (frivilligt)','videoUrl','url','maxlength="2000" placeholder="https://…"')}${field('Tillstånd för extern videokälla (om länk används)','rightsNote','text','maxlength="1000"')}<label class="check-label"><input type="checkbox" name="rightsConfirmed"><span>Om videolänk används är tillståndet klarlagt. Ingen video lagras eller bäddas in hos VDK.</span></label>${formFooter('Skapa videocoachuppdrag')}</form></div>`:notice('Utse en videocoach under Medlemmar. Uppdrag kräver en verifierad historisk match med en aktiv medlem.')}<h2>Tilldelade uppdrag</h2><div class="coaching-history">${coachings.map(c=>`<article class="card"><h3>${esc(c.home)} – ${esc(c.away)}</h3><p>${date(c.starts_at)} · ${esc(c.competition_name)}<br>Coach: ${esc(c.coach_name)}<br>Domare: ${esc(c.member_name)}<br>Status: ${esc(statusLabel(c.status))}<br>Skapad: ${date(c.created_at)}${c.published_at?'<br>Publicerad: '+date(c.published_at):''}</p></article>`).join('')||'<p>Inga uppdrag ännu.</p>'}</div>`;}
  else if(tab==='statistik'){const s=await loadSettings();const {statistics}=await api('/admin/statistics?season='+encodeURIComponent(s.season));body=`<h2>VDK ${esc(s.season)}</h2>${notice('Sammanställningen avser endast VDK-medlemmarnas matchunderlag. Varje externt match-id räknas en gång.')}<div class="card"><p>${statistics.members} aktiva domarmedlemmar</p>${statsView(statistics)}</div>`;}
  else{const {applications,members,canGrantAdmin}=await api('/admin/members');body=`<h2>Medlemsansökningar</h2>${applications.length?`<div class="card table-wrap"><table><thead><tr><th>Medlem</th><th>Säsong</th><th>Status</th><th>Åtgärd</th></tr></thead><tbody>${applications.map(a=>`<tr><td>${esc(a.name)}<br>${esc(a.email)}</td><td>${esc(a.season)}<br>${esc(membershipNames[a.category]||'Aktiv domare')}<br>${esc(a.organization||'')}<br>${money(a.amount||100)}</td><td>${esc(a.category==='business'&&a.status==='active'?'Gåva bekräftad':statusLabel(a.status))}<br>${a.paid?'Betalning verifierad':'Betalning ej verifierad'}</td><td>${a.status==='pending'?`<button class="button payment-confirm" data-id="${a.id}">Bekräfta Swish ${money(a.amount)}</button><button class="button button-outline member-approve" data-id="${a.id}" data-category="${a.category}" ${a.paid?'':'disabled'}>${a.category==='business'?'Bekräfta gåvan':'Godkänn och skicka aktivering'}</button>`:a.status==='approved'?`<button class="button button-outline resend-activation" data-id="${a.id}">Skicka ny aktiveringslänk</button>`:a.status==='expired'&&a.category!=='business'?`<button class="button button-outline member-reactivate" data-id="${a.id}">Återaktivera medlemskap</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Inga medlemsansökningar.','Ansökningar visas här när medlemskapet öppnas.')}<h2 style="margin-top:2rem">Medlemsregister</h2><div class="card table-wrap"><table><thead><tr><th>Namn</th><th>E-post</th><th>Roller</th><th>Behörighet</th></tr></thead><tbody>${members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${m.roles.map(esc).join(', ')}</td><td>${m.canCoach||m.roles.includes('VIDEO_COACH')?`<button class="button button-outline role-change" data-id="${m.id}" data-role="VIDEO_COACH" data-enabled="${!m.roles.includes('VIDEO_COACH')}">${m.roles.includes('VIDEO_COACH')?'Ta bort videocoachroll':'Gör till videocoach'}</button>${canGrantAdmin&&m.id!==user.id&&!m.roles.includes('ADMIN')?`<button class="button button-outline grant-admin" data-id="${m.id}" data-name="${esc(m.name)}">Ge adminroll</button>`:''}`:'Aktivt medlemskap krävs'}</td></tr>`).join('')}</tbody></table></div>`;}
  if(!tab){const {applications}=await api('/admin/members');const closable=applications.filter(x=>['active','approved'].includes(x.status)&&x.user_id!==user.id);if(closable.length)body+=`<div class="card" style="margin-top:1.5rem"><h2>Avsluta säsongsmedlemskap</h2><p>Åtkomsten till Mina sidor stängs och befintliga sessioner avslutas.</p><form id="close-membership"><div class="field"><label for="membershipId">Medlemskap</label><select name="membershipId" id="membershipId">${closable.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.season)}</option>`).join('')}</select></div><label class="check-label"><input type="checkbox" required><span>Jag bekräftar att medlemskapet ska avslutas.</span></label>${formFooter('Avsluta medlemskapet')}</form></div>`;}
  return `<section class="page container"><div class="portal-head"><div><p class="eyebrow">VDK administration</p><h1>Administrera kollektivet.</h1></div><a class="button button-outline button-small" href="#/mina-sidor">Till Mina sidor</a></div><nav class="tabs" aria-label="Admin">${tabs.map(([p,t])=>`<a href="#/admin${p?'/'+p:''}" class="${p===tab?'active':''}">${t}</a>`).join('')}</nav>${body}</section>`;
}
async function route({focusResults=false}={}){closeBoards();document.querySelector('#development-dialog[open]')?.close();if(['vdk.nu','www.vdk.nu'].includes(location.hostname)&&/^#\/(logga-in|registrera|mina-sidor|admin|aktivera|nytt-losenord|aterstall|medlemskap\/)/.test(location.hash)){location.replace('https://vdk-members.soren-johansson-7.workers.dev/'+location.hash);return;}const epoch=++pageEpoch;const hash=(location.hash.slice(1)||'/');const path=hash.split('?')[0];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===path||(a.dataset.nav==='/medlemskap'&&path.startsWith('/medlemskap/'))));document.querySelector('#navigation').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');main.innerHTML=`<div class="loading" role="status">${focusResults?'Laddar statistik…':'Laddar…'}</div>`;let html;
  try{if(!['vdk.nu','www.vdk.nu'].includes(location.hostname)){try{user=(await api('/me')).user;}catch{user=null;}}updateAccountNavigation();if(path==='/logga-in')html=user?await portal(''):login();else if(path==='/registrera'||path.startsWith('/registrera/')){const category=Object.keys(membershipPaths).find(key=>key!=='business'&&membershipPaths[key]===path.split('/')[2]);html=await registration(category);}else if(path==='/')html=home();else if(path==='/om-vdk')html=about();else if(path==='/styrelsen')html=board();else if(path==='/medlemskap')html=membership();else if(path.startsWith('/medlemskap/')){const category=Object.keys(membershipPaths).find(key=>membershipPaths[key]===path.split('/')[2]);html=category?await membershipDetail(category):membership();}else if(path==='/stadgar')html=statutes();else if(path==='/regel-demo'){if(user){location.assign('/member-rules/');return;}html=ruleDemo();}else if(path==='/kunskapsnivaer'){html=knowledgeLevels();const step=new URLSearchParams(hash.split('?')[1]).get('step');if(step!==null&&/^\d+$/.test(step)&&developmentSteps[Number(step)])setTimeout(()=>openDevelopmentStep(Number(step)),0);}else if(path==='/for-domare')html=referees();else if(path==='/sponsorer')html=sponsors();else if(path==='/nyheter')html=news();else if(path==='/faq')html=page('FAQ – vanliga frågor.','Svar om VDK, medlemskap och vår verksamhet.',faqSection());else if(path==='/kontakt')html=contact();else if(path==='/integritet')html=privacy();else if(path==='/aktivera')html=passwordPage();else if(path==='/nytt-losenord')html=passwordPage(true);else if(path==='/aterstall')html=resetPage();else if(path.startsWith('/mina-sidor'))html=await portal(path.split('/')[2]||'');else if(path.startsWith('/admin'))html=await admin(path.split('/')[2]||'');else html=page('Sidan finns inte.','Länken verkar inte leda till någon sida.','<a class="button" href="#/">Till startsidan</a>');}
  catch(e){html=page('Det gick inte att hämta sidan.','Försök igen om en stund.',notice(esc(e.message),'error')+'<a class="button" href="#/mina-sidor">Till Mina sidor</a>');}
  if(epoch!==pageEpoch)return;main.innerHTML=html;bind();const results=focusResults&&document.querySelector('#statistics-result-heading');if(results){const filters=document.querySelector('#statistics-filters');if(filters&&window.matchMedia('(max-width:650px)').matches)filters.open=false;results.focus({preventScroll:true});(document.querySelector('#statistics-results')||results).scrollIntoView({block:'start',behavior:'instant'});}else{window.scrollTo(0,0);main.focus({preventScroll:true});}const title=main.querySelector('h1')?.textContent||'VDK';document.title=`${title} | VDK`;
}
function bind(){
 document.querySelector('#comments-search')?.addEventListener('submit',async e=>{e.preventDefault();history.pushState(null,'','#/mina-sidor/kommentarer?'+new URLSearchParams(new FormData(e.target)));await route();const results=document.querySelector('#comments-results');results?.focus({preventScroll:true});results?.scrollIntoView({block:'start',behavior:'instant'});});
 document.querySelector('#match-comment-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{await api('/matches/'+e.target.dataset.match+'/comments',{method:'POST',body:{comment:data.comment}});toast('Kommentaren är sparad.');await route();});});
 document.querySelectorAll('.delete-match-comment').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await api('/matches/'+button.dataset.match+'/comments/'+button.dataset.comment+'/delete',{method:'POST',body:{}});toast('Kommentaren är borttagen.');await route();}catch(error){button.disabled=false;toast(error.message);}}));

 document.querySelector('#special-message-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,channel=form.dataset.channel,isBroadcast=Object.hasOwn(broadcastGroups,channel);if(isBroadcast&&!confirm('Skicka meddelandet till '+broadcastGroups[channel].toLocaleLowerCase('sv-SE')+' med aktiva konton?'))return;submit(form,async data=>{const r=await api('/messages/'+(isBroadcast?'broadcast':'suggestions'),{method:'POST',body:{message:data.message,clientId:form.dataset.clientId,...(isBroadcast?{group:channel}:{})}});form.reset();form.dataset.clientId=crypto.randomUUID();toast(isBroadcast?'Skickat till '+r.count+' medlemmar.':'Tack! Ditt förslag har skickats till administratörerna.');});});
 document.querySelector('#message-recipient')?.addEventListener('submit',async e=>{e.preventDefault();history.pushState(null,'','#/mina-sidor/meddelanden?'+new URLSearchParams(new FormData(e.target)));await route();});
 document.querySelector('#refresh-messages')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await refreshMessageConversation();}catch(error){toast(error.message);}finally{e.target.disabled=false;}});
 document.querySelector('#message-email')?.addEventListener('change',async e=>{const checkbox=e.target;checkbox.disabled=true;try{await api('/messages/preferences',{method:'POST',body:{emailEnabled:checkbox.checked}});toast(checkbox.checked?'Mejlavisering är på.':'Mejlavisering är av.');}catch(error){checkbox.checked=!checkbox.checked;toast(error.message);}finally{checkbox.disabled=false;}});
 document.querySelector('#message-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target;submit(form,async data=>{await api('/messages',{method:'POST',body:{recipientId:Number(form.dataset.peer),message:data.message,clientId:form.dataset.clientId}});form.reset();form.dataset.clientId=crypto.randomUUID();await refreshMessageConversation();toast('Meddelandet är skickat.');});});

  document.querySelectorAll('.password-toggle').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.getAttribute('aria-controls'));const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Dölj':'Visa';button.setAttribute('aria-pressed',String(show));}));
 document.querySelector('#matches-season')?.addEventListener('change',async e=>{history.pushState(null,'','#/mina-sidor/matcher?'+new URLSearchParams({season:e.target.value}));await route();});
 document.querySelector('#stats-season')?.addEventListener('change',async e=>{const form=e.target.form,params=new URLSearchParams(new FormData(form));params.set('against',String(form.elements.against.checked));history.pushState(null,'',(location.hash.startsWith('#/mina-sidor/forbund')?'#/mina-sidor/forbund?':'#/mina-sidor/statistik?')+params);await route();});
 document.querySelector('#availability-filter')?.addEventListener('submit',async e=>{e.preventDefault();history.pushState(null,'','#/mina-sidor/aterbud?'+new URLSearchParams(new FormData(e.target)));await route({focusResults:true});});
  document.querySelector('#close-membership')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{await api(`/admin/applications/${data.membershipId}/close`,{method:'POST',body:{}});toast('Säsongsmedlemskapet är avslutat.');await route();});});
  document.querySelector('#membership-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{const result=await api('/applications',{method:'POST',body:{...data,consent:data.consent==='on'}});e.target.outerHTML=`<div class="registration-receipt" tabindex="-1"><h3>${result.category==='business'?'Anmälan mottagen':'Du är registrerad'}</h3>${result.category==='business'?'':notice('Öppna mejlet från VDK och välj ditt lösenord via aktiveringslänken. Därefter kan du logga in. Kontrollera även skräpposten.','success')}<h3>Betalning</h3><p>Swisha <strong>${money(result.fee)}</strong> till <strong>${esc(result.swishNumber)}</strong>.</p><p>Ange <strong>${esc(result.paymentReference)}</strong> som meddelande.</p><p>${result.category==='business'?'VDK bekräftar gåvan när betalningen har kontrollerats.':'Medlemsfunktionerna öppnas när VDK har registrerat och godkänt betalningen. Du kan logga in innan dess.'}</p><div class="inline-actions">${result.category==='business'?'':'<a class="button" href="#/logga-in">Till inloggningen</a>'}<a class="text-link" href="#/kontakt">Behöver du hjälp?</a></div></div>`;document.querySelector('.registration-receipt').focus();});});
  document.querySelector('#login-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{user=(await api('/auth/login',{method:'POST',body:data})).user;history.replaceState(null,'','#/mina-sidor');await route();});});
  document.querySelector('#logout')?.addEventListener('click',e=>logout(e.currentTarget));
  document.querySelector('#password-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{if(data.password!==data.confirm)throw new Error('Lösenorden stämmer inte överens.');const token=new URLSearchParams(location.hash.split('?')[1]).get('token');if(!token)throw new Error('Aktiveringslänken är ofullständig. Be VDK om en ny länk.');await api(e.target.dataset.reset==='true'?'/auth/reset':'/auth/activate',{method:'POST',body:{token,password:data.password}});history.replaceState(null,'','#/logga-in');toast('Lösenordet är sparat. Du kan nu logga in.');await route();});});
  document.querySelector('#reset-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{await api('/auth/request-reset',{method:'POST',body:data});e.target.outerHTML=notice('Om adressen hör till ett aktiverat konto har vi skickat en återställningslänk.','success');});});
  bindProfilesAndSearch();
  document.querySelector('#remove-photo')?.addEventListener('click',e=>action(e.currentTarget,'/profile/photo',{remove:true},'Profilbilden är borttagen.'));
  document.querySelector('#regional-filter')?.addEventListener('submit',e=>{e.preventDefault();applyStatisticsFilters(e.target,'/mina-sidor/varmland');});
  document.querySelector('#stats-filter')?.addEventListener('submit',e=>{e.preventDefault();applyStatisticsFilters(e.target,location.hash.startsWith('#/mina-sidor/forbund')?'/mina-sidor/forbund':'/mina-sidor/statistik');});
  document.querySelector('#coach-application')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{await api('/coach-applications',{method:'POST',body:data});toast('Din videocoachansökan är mottagen.');await route();});});
  document.querySelectorAll('.payment-confirm').forEach(b=>b.addEventListener('click',()=>action(b,`/admin/applications/${b.dataset.id}/payment`,{},'Betalningen är verifierad.')));
  document.querySelectorAll('.member-approve,.resend-activation').forEach(b=>b.addEventListener('click',()=>action(b,`/admin/applications/${b.dataset.id}/approve`,{},b.dataset.category==='business'?'Gåvan är bekräftad.':'Aktiveringslänken har skickats.')));
  document.querySelectorAll('.coach-decision').forEach(b=>b.addEventListener('click',()=>action(b,`/admin/coach-applications/${b.dataset.id}`,{status:b.dataset.status},'Ansökan är behandlad.')));
  document.querySelectorAll('.member-reactivate').forEach(b=>b.addEventListener('click',()=>action(b,`/admin/applications/${b.dataset.id}/reactivate`,{},'Medlemskapet är återaktiverat. Logga in med ditt befintliga lösenord.')));
  document.querySelectorAll('.grant-admin').forEach(b=>b.addEventListener('click',()=>{if(confirm('Ge '+b.dataset.name+' ADMIN? Personen får tillgång till VDK:s administration och medlemsuppgifter. Endast du kan utse fler administratörer.'))action(b,`/admin/members/${b.dataset.id}/grant-admin`,{},'Adminrollen är tillagd.');}));
  document.querySelectorAll('.role-change').forEach(b=>b.addEventListener('click',()=>action(b,`/admin/members/${b.dataset.id}/role`,{role:b.dataset.role,enabled:b.dataset.enabled==='true'},'Behörigheten är uppdaterad.')));
  document.querySelector('#member-search')?.addEventListener('input',e=>{const search=e.target.value.trim().normalize('NFC').toLocaleLowerCase('sv-SE');let count=0;document.querySelectorAll('.member-directory-card').forEach(card=>{card.hidden=!card.dataset.name.includes(search);if(!card.hidden)count++;});document.querySelector('#member-count').textContent=count+' medlemmar';document.querySelector('#no-members').hidden=count>0;});
  bindDocumentUpload();bindBoardViews();
  bindCoaching();
  document.querySelector('#assignment-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{await api('/admin/coachings',{method:'POST',body:{...data,matchId:Number(data.matchId),coachId:Number(data.coachId),memberId:Number(data.memberId),rightsConfirmed:data.rightsConfirmed==='on'}});toast('Coachuppdraget är skapat.');await route();});});
}
async function action(button,path,body,message){button.disabled=true;try{await api(path,{method:'POST',body});toast(message);await route();}catch(e){toast(e.message);button.disabled=false;}}
document.querySelector('[data-logout]').addEventListener('click',e=>logout(e.currentTarget));
document.querySelector('.menu-toggle').addEventListener('click',e=>{const button=e.currentTarget;const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));document.querySelector('#navigation').classList.toggle('open',!open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#navigation').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}});
function closeMembershipMenus(){document.querySelectorAll('[data-membership-menu]').forEach(button=>{button.setAttribute('aria-expanded','false');const menu=document.getElementById(button.getAttribute('aria-controls'));if(menu)menu.hidden=true;});}
document.addEventListener('click',event=>{const button=event.target.closest('[data-membership-menu]');if(button){const wasOpen=button.getAttribute('aria-expanded')==='true';closeMembershipMenus();const menu=document.getElementById(button.getAttribute('aria-controls'));if(menu&&!wasOpen){if(button.closest('.hero')){const rect=button.getBoundingClientRect();menu.style.position='fixed';menu.style.left=Math.max(12,Math.min(rect.left,innerWidth-310))+'px';menu.style.top=Math.min(rect.bottom+10,innerHeight-350)+'px';}button.setAttribute('aria-expanded','true');menu.hidden=false;}}else if(!event.target.closest('.membership-mini-menu'))closeMembershipMenus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const open=document.querySelector('[data-membership-menu][aria-expanded="true"]');closeMembershipMenus();open?.focus();}});
window.addEventListener('resize',closeMembershipMenus);
window.addEventListener('hashchange',()=>{closeMembershipMenus();route();});
route();

function ruleDemo(){const questions=[...demoQuestions].sort(()=>Math.random()-.5);window.vdkDemoOrder=questions;return page('Prova regelgeneratorn.','Tio lätta standardfrågor. Du behöver inget konto för demon.',`<p class="notice">Fullversionen är för godkända aktiva medlemmar, stödmedlemmar och föreningsmedlemmar. Betalningen måste vara kontrollerad och ansökan godkänd av en administratör.</p><form id="rule-demo-form">${questions.map((q,i)=>`<fieldset class="card demo-question"><legend>Fråga ${i+1} av 10</legend><h2>${esc(q.q)}</h2>${q.a.map((a,j)=>`<label class="check-label"><input type="radio" name="q${q.id}" value="${j}" required><span>${esc(a)}</span></label>`).join('')}<div data-demo-feedback="${q.id}"></div></fieldset>`).join('')}<button class="button" type="submit">Visa resultat</button><div id="demo-result" tabindex="-1" aria-live="polite"></div></form><div class="inline-actions"><a class="button" href="#/medlemskap">Bli medlem</a><a class="button button-outline" href="#/mina-sidor/regler">Fullversion för medlemmar</a></div><p><a class="text-link" href="https://www.innebandy.se/tavling/regler-och-direktiv" target="_blank" rel="noopener">Officiella spelregler och direktiv</a></p>`);}
function knowledgeLevels(){const levels=['Grön serie / poolspel','Blå serie','Röd 7–Röd 4','Röd 3–Röd 1','Lilla VM','H5 / D3','H4 / D2 / DJ17','H3 / HJ17 / DM','D1 / DJ18','H2 / HJ18 / DM'];const portrait=`<svg class="development-portrait" viewBox="0 390 500 650" role="img" aria-label="Innebandydomare som visar ett tecken"><defs><clipPath id="referee-silhouette"><path d="M0 750 L18 650 L48 588 L84 530 L113 508 L106 477 L101 449 L121 423 L161 408 L199 416 L223 435 L229 468 L220 493 L204 510 L242 527 L286 524 L354 491 L438 446 L463 421 L480 415 L486 428 L475 449 L456 465 L440 484 L380 540 L315 593 L270 632 L255 731 L260 820 L250 896 L255 1040 L71 1040 L72 900 L36 841 L0 851 Z"/></clipPath></defs><image href="assets/development-illustration.png" width="1223" height="1286" clip-path="url(#referee-silhouette)"/></svg>`;return `<section class="development-page"><div class="development-arena"><div class="development-board"><div class="development-intro"><p class="eyebrow">Värmlands Domarkollektiv</p><h1>DOMAR<span>UTVECKLING</span></h1><p class="development-subtitle">Steg för steg – från första signal till avancerad matchledning</p><p>En tydlig vägledning för din utveckling som domare. Klicka på varje steg för att läsa om färdigheterna, coachens observationer och nästa mål.</p><blockquote>Du behöver inte vara färdig.<br>Du behöver vara redo för nästa steg.</blockquote>${portrait}</div><div class="development-stairs" aria-label="Utvecklingsstegen">${developmentSteps.map((step,i)=>`<button type="button" class="development-row" style="--step:${i}" data-development-step="${i}" aria-haspopup="dialog"><span class="step-number">${i+1}</span>${icon(['whistle','growth','shield','growth','whistle','people','people','growth','shield','shield','shield','growth'][i])}<span class="step-copy"><strong>${esc(step.title)}</strong><small>${esc(step.short)}</small><span class="step-level">${esc(step.level)}</span></span><span class="step-arrow" aria-hidden="true">›</span></button>`).join('')}</div><aside class="match-levels"><p class="eyebrow">Utveckling hela vägen</p><h2>Serier & nivåer</h2><ol>${levels.map((level,i)=>`<li class="level-band level-band-${i}"><strong>${esc(level)}</strong></li>`).join('')}</ol><p class="level-note">Nivåerna är vägledande. Utvecklingssteg är inte ranking eller behörighet. Tillsättning beslutas av ansvarig organisation.</p></aside></div><div class="development-benefits"><div>${icon('growth')}<span><strong>Individuell utveckling</strong><small>Sätt mål och följ din resa.</small></span></div><div>${icon('people')}<span><strong>Gemenskap</strong><small>Vi växer tillsammans.</small></span></div><div>${icon('shield')}<span><strong>Trygghet</strong><small>Starkare domare. Starkare innebandy.</small></span></div><a class="button" href="#/medlemskap">Bli medlem i VDK →</a></div></div><dialog id="development-dialog" class="development-dialog" aria-labelledby="development-dialog-title"><button type="button" class="development-close" aria-label="Stäng steg">×</button><div id="development-dialog-content"></div></dialog></section>`;}
function openDevelopmentStep(index){const step=developmentSteps[index],dialog=document.querySelector('#development-dialog');if(!step||!dialog)return;const list=items=>`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`;document.querySelector('#development-dialog-content').innerHTML=`<p class="eyebrow">Steg ${index+1}</p><h2 id="development-dialog-title">${esc(step.title)}</h2><p class="lead">${esc(step.short)}</p><h3>Det här innebär steget</h3>${step.description.map(p=>`<p>${esc(p)}</p>`).join('')}<h3>Det här tränar du på</h3>${list(step.skills)}<h3>Coachen tittar efter</h3>${list(step.criteria)}<h3>Vanliga utvecklingspunkter</h3>${list(step.issues)}<h3>Så tar du nästa steg</h3>${list(step.goals)}<h3>Matchnivåer att förbereda sig för</h3><p>${esc(step.level)}</p><p class="notice">Matchnivåerna är vägledning för utveckling, inte rätt till en viss tillsättning. Regelverket styr alltid beslut och bestraffningar.</p>`;dialog.showModal();dialog.scrollTop=0;document.body.classList.add('development-open');dialog.addEventListener('close',()=>document.body.classList.remove('development-open'),{once:true});}
document.addEventListener('click',event=>{const opener=event.target.closest('[data-development-step]');if(opener){openDevelopmentStep(Number(opener.dataset.developmentStep));return;}const dialog=document.querySelector('#development-dialog');if(!dialog?.open)return;if(event.target.closest('.development-close'))dialog.close();else if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
document.addEventListener('submit',event=>{if(event.target.id!=='rule-demo-form')return;event.preventDefault();const answers=new FormData(event.target);let correct=0;for(const q of window.vdkDemoOrder){const ok=Number(answers.get('q'+q.id))===q.x;if(ok)correct++;event.target.querySelector(`[data-demo-feedback="${q.id}"]`).innerHTML=`<p class="notice ${ok?'success':'error'}"><strong>${ok?'Rätt':'Fel'} – ${esc(q.r)}</strong><br>${esc(q.e)} <small>${esc(q.s)}</small></p>`;}const result=document.querySelector('#demo-result');result.innerHTML=`<h2>${correct} av 10 rätt</h2><p>Vill du träna vidare? Fullversionen kräver godkänt aktivt medlemskap, stödmedlemskap eller föreningsmedlemskap.</p>`;result.focus();result.scrollIntoView({block:'center'});});

setInterval(async()=>{if(!user||document.hidden||!location.hash.startsWith('#/mina-sidor'))return;try{await refreshMessageConversation();const d=await api('/messages/unread');messageUnread=d.unread;document.querySelectorAll('[data-unread-badge]').forEach(el=>{el.textContent=String(d.unread);el.hidden=!d.unread;});}catch{}},30000);

window.addEventListener('beforeunload',event=>{if(document.querySelector('.coaching-editor[data-dirty="true"]')){event.preventDefault();event.returnValue='';}});
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#/"]');if(link&&document.querySelector('.coaching-editor[data-dirty="true"]')&&!confirm('Du har osparade ändringar i protokollet. Lämna utan att spara?'))event.preventDefault();},true);

function closePortalMenu({focus=false}={}){const button=document.querySelector('[data-portal-menu]');const menu=document.getElementById('portal-menu');if(!button||!menu)return;menu.hidden=true;button.setAttribute('aria-expanded','false');if(focus)button.focus();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-portal-menu]');if(button){const menu=document.getElementById('portal-menu');if(!menu)return;const open=button.getAttribute('aria-expanded')!=='true';menu.hidden=!open;button.setAttribute('aria-expanded',String(open));}else if(!event.target.closest('.portal-menu-wrap'))closePortalMenu();});
document.addEventListener('keydown',event=>{const button=document.querySelector('[data-portal-menu]');if(event.key==='Escape'&&button?.getAttribute('aria-expanded')==='true'){event.preventDefault();closePortalMenu({focus:true});}if(event.key==='ArrowDown'&&event.target===button){event.preventDefault();const menu=document.getElementById('portal-menu');menu.hidden=false;button.setAttribute('aria-expanded','true');menu.querySelector('a')?.focus();}});
document.addEventListener('focusin',event=>{if(!event.target.closest('.portal-menu-wrap'))closePortalMenu();});

function memberDirectoryMarkup(members){return `<h2>Medlemmar</h2><p>Här hittar du VDK:s medlemmar med tillgång till Mina sidor.</p><div class="field"><label for="member-search">Sök medlem</label><input id="member-search" type="search" placeholder="Sök på namn" autocomplete="off"></div><p id="member-count" role="status">${members.length} medlemmar</p><div class="content-grid member-directory">${members.map(m=>`<article class="card member-directory-card" data-name="${esc(m.name.normalize('NFC').toLocaleLowerCase('sv-SE'))}"><h3><a class="text-link" href="#/mina-sidor/medlemsprofil?id=${m.id}">${esc(m.name)}</a></h3>${m.city||m.departure?`<p>${esc(m.city)}${m.departure?'<br>Åker från: '+esc(m.departure):''}</p>`:''}${m.id===user.id?'<span class="badge">Du</span>':`<a class="button button-outline button-small" href="#/mina-sidor/meddelanden?to=${m.id}">Skriv meddelande</a>`}</article>`).join('')}</div><p id="no-members" ${members.length?'hidden':''}>Inga medlemmar matchar sökningen.</p>`;}
function isSupport(){return user?.membershipCategory==='support'&&!user.roles.includes('ADMIN');}
async function supportHome(){const {memberships}=await api('/membership');const membership=memberships.find(m=>m.season===user.season),enabled=membership?.paid&&membership?.status==='active';let content=`<section class="card" id="support-membership"><h2>Mitt medlemskap</h2><p>${esc(user.name)} · Stödmedlem</p><p>Säsong ${esc(user.season)} · ${esc(statusLabel(membership?.status||'pending'))}</p><p>Betalning: ${membership?.paid?'Bekräftad':'Ej bekräftad'} · 100 kr</p><p>${enabled?'<a class="button" href="/member-rules/">Regelgenerator</a>':''}</p><p>Tack för att du stödjer Värmlands domarkår. Du kan lämna förslag och bidra till verksamheten.</p></section>`;
if(!enabled)return portalShell('',content+notice('Medlemsfunktionerna öppnas när VDK har registrerat din betalning och godkänt medlemskapet.'));
const {members}=await api('/members');content+=`<section class="support-section" id="support-messages">${await messagesView()}</section><section class="support-section" id="support-members">${memberDirectoryMarkup(members)}</section><section class="support-section" id="support-board"><h2>Domartavlan</h2><p>Rita och visa positioner på innebandyplanen. Tavlan sparas inte när du lämnar sidan.</p><div id="standalone-board"></div></section>`;if(location.hash.includes('?'))setTimeout(()=>document.querySelector('#support-messages')?.scrollIntoView({block:'start'}),0);return portalShell('',content);
}

const documentSections={sif:'Svenska Innebandyförbundet',vibf:'Värmlands Innebandyförbund',vdk:'Värmlands Domarkollektiv'};
async function documentsView(admin=false){const id=new URLSearchParams(location.hash.split('?')[1]).get('id');if(id&&!admin){const {document:d}=await api('/documents/'+encodeURIComponent(id));return `<h2>${esc(d.title)}</h2><p>${esc(documentSections[d.section])}</p><div class="inline-actions"><a class="button document-download" data-document="${d.id}" href="${esc(apiBase)}/api/documents/${d.id}/pdf">Ladda ner PDF</a><a class="text-link" href="#/mina-sidor/dokument">Alla dokument</a></div><article class="card document-reading"><div class="document-text">${esc(d.content)}</div></article>`;}
const {documents}=await api('/documents');return `<h2>Dokument</h2><p>Dokument för VDK:s medlemmar. Läs hela texten på sidan eller ladda ner PDF-versionen.</p>${admin?`<section class="card"><h3>Ladda upp dokument</h3><form id="document-upload"><div class="field"><label for="document-file">PDF, Word (.docx) eller text (.txt), högst 5 MB</label><input type="file" id="document-file" accept=".pdf,.docx,.txt" required></div><button type="button" class="button button-outline" id="document-prepare">Läs in dokument</button><p id="document-progress" role="status"></p><div class="field"><label for="document-title">Rubrik</label><input id="document-title" name="title" required maxlength="180"></div><div class="field"><label for="document-section">Sektion</label><select id="document-section" name="section">${Object.entries(documentSections).map(([key,label])=>`<option value="${key}">${esc(label)}</option>`).join('')}</select></div><div class="field"><label for="document-content">Hela dokumentets innehåll</label><textarea id="document-content" name="content" required maxlength="80000" rows="14"></textarea><small>Kontrollera texten mot originalet. För skannade PDF:er behöver texten kompletteras. Word och text får en PDF med detta innehåll; originalets sidlayout bevaras inte.</small></div><label class="check-label"><input name="reviewed" type="checkbox" required><span>Jag har kontrollerat att hela dokumentets innehåll finns med och stämmer med PDF-versionen.</span></label>${formFooter('Publicera dokument')}</form></section>`:''}${Object.entries(documentSections).map(([key,label])=>`<section class="support-section"><h3>${esc(label)}</h3>${documents.filter(d=>d.section===key).map(d=>`<article class="card"><h4>${esc(d.title)}</h4><div class="inline-actions"><a class="text-link" href="#/mina-sidor/dokument?id=${d.id}">Läs dokumentet</a><a class="text-link document-download" data-document="${d.id}" href="${esc(apiBase)}/api/documents/${d.id}/pdf">Ladda ner PDF</a></div></article>`).join('')||'<p>Inga dokument publicerade ännu.</p>'}</section>`).join('')}`;}
function bindDocumentUpload(){let converter;const load=async()=>converter||(converter=await import('./assets/documents/converter.js'));const form=document.querySelector('#document-upload');document.querySelector('#document-file')?.addEventListener('change',()=>{form.documentSource=null;form.querySelector('[name=reviewed]').checked=false;document.querySelector('#document-content').value='';});document.querySelector('#document-prepare')?.addEventListener('click',async e=>{const b=e.target,progress=document.querySelector('#document-progress');b.disabled=true;progress.textContent='Läser dokumentet…';try{const file=document.querySelector('#document-file').files[0];const c=await load();const source=await c.readDocument(file);if(file!==document.querySelector('#document-file').files[0])throw Error('Filen ändrades. Läs in den valda filen igen.');form.documentSource=source;document.querySelector('#document-content').value=form.documentSource.content;if(!document.querySelector('#document-title').value)document.querySelector('#document-title').value=file.name.replace(/\.[^.]+$/,'');progress.textContent=form.documentSource.content?'Dokumentet är inläst. Granska innehållet före publicering.':'PDF-filen saknar läsbar text. Fyll i hela innehållet före publicering.';}catch(error){progress.textContent=error.message;}finally{b.disabled=false;}});
form?.addEventListener('submit',e=>{e.preventDefault();submit(form,async data=>{if(!form.documentSource)throw Error('Läs in dokumentet först.');const c=await load(),pdf=form.documentSource.originalPdf?form.documentSource.pdf:await c.textPdf(data.title,data.content);const r=await api('/admin/documents',{method:'POST',body:{title:data.title,section:data.section,content:data.content,pdf:c.base64Pdf(pdf)}});toast('Dokumentet är publicerat.');location.hash='#/mina-sidor/dokument?id='+r.id;});});
document.querySelectorAll('.document-download').forEach(a=>a.addEventListener('click',async e=>{e.preventDefault();try{const r=await fetch(apiBase+'/api/documents/'+a.dataset.document+'/pdf',{credentials:'include'});if(!r.ok)throw Error('Dokumentet kunde inte hämtas. Logga in och försök igen.');const url=URL.createObjectURL(await r.blob()),link=document.createElement('a');link.href=url;link.download='VDK-dokument-'+a.dataset.document+'.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){toast(error.message);}}));}
const profileFields=[['contact_email','E-post att dela','email',254],['phone','Telefonnummer','tel',40],['city','Ort','text',100],['address','Adress (valfritt)','text',200],['departure','Jag åker oftast från','text',200]];
async function profileView(){const {profile:p}=await api('/profile');return `<section class="card profile-editor"><h2>Min profil</h2><p>Fyll bara i det du vill dela. Kontaktuppgifterna används inte för att ändra ditt inlogg.</p><form id="member-profile-form"><div class="field"><label for="profile-name">Namn</label><input id="profile-name" value="${esc(p.name)}" readonly><small>Namnet kommer från ditt medlemskonto. Kontakta admin om det behöver ändras.</small></div>${profileFields.map(([key,label,type,max])=>`<div class="field"><label for="profile-${key}">${label}</label><input id="profile-${key}" name="${key}" type="${type}" maxlength="${max}" value="${esc(p[key])}"></div>`).join('')}<div class="field"><label for="profile-bio">Om mig / samåkning</label><textarea id="profile-bio" name="bio" maxlength="1000" rows="4" placeholder="Till exempel när du gärna samåker eller hur kollegor når dig.">${esc(p.bio)}</textarea></div><label class="check-label"><input type="checkbox" name="share_profile" ${p.share_profile?'checked':''}><span>Visa dessa kontaktuppgifter för andra godkända VDK-medlemmar</span></label><label class="check-label"><input type="checkbox" name="share_photo" ${p.share_photo?'checked':''}><span>Visa min profilbild för andra godkända VDK-medlemmar</span></label><p>Du kan när som helst ändra, tömma eller sluta dela uppgifterna.</p>${formFooter('Spara profil')}</form></section><section class="card profile-editor"><h2>Profilbild</h2>${user.hasPhoto?`<img class="profile-photo" src="${esc(apiBase)}/api/profile/photo" alt="Din profilbild">`:'<p>Ingen profilbild uppladdad ännu.</p>'}<form id="profile-photo-form"><div class="field"><label for="profile-photo">Välj bild</label><input id="profile-photo" name="photo" type="file" accept="image/png,image/jpeg,image/webp" required><small>JPEG, PNG eller WebP, upp till 30 MB. Vi anpassar bilden automatiskt – du behöver inte minska den själv.</small></div>${formFooter('Spara profilbild')}</form>${user.hasPhoto?'<button id="remove-photo" class="button button-quiet">Ta bort profilbild</button>':''}</section>`;}
async function sharedProfileView(){const id=new URLSearchParams(location.hash.split('?')[1]).get('id');if(!/^\d+$/.test(id||''))throw Error('Välj en medlem i medlemslistan.');const {profile:p}=await api('/members/'+id+'/profile');return `<article class="card profile-editor"><p><a class="text-link" href="#/mina-sidor/medlemmar">← Medlemmar</a></p><h2>${esc(p.name)}</h2>${p.hasPhoto?`<img class="profile-photo" src="${esc(apiBase)}/api/members/${id}/photo" alt="Profilbild för ${esc(p.name)}">`:''}<dl class="profile-contact">${profileFields.filter(([key])=>p[key]).map(([key,label])=>`<div><dt>${label}</dt><dd>${key==='contact_email'?`<a class="text-link" href="mailto:${esc(p[key])}">${esc(p[key])}</a>`:key==='phone'?`<a class="text-link" href="tel:${esc(p[key].replace(/[^+\d]/g,''))}">${esc(p[key])}</a>`:esc(p[key])}</dd></div>`).join('')}</dl>${p.bio?`<h3>Om mig / samåkning</h3><p class="profile-bio">${esc(p.bio)}</p>`:!profileFields.some(([key])=>p[key])?'<p>Medlemmen har inte delat några kontaktuppgifter ännu.</p>':''}${Number(id)!==user.id?`<a class="button" href="#/mina-sidor/meddelanden?to=${id}">Skriv meddelande</a>`:'<a class="button" href="#/mina-sidor/profil">Redigera min profil</a>'}</article>`;}
async function prepareProfilePhoto(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Välj JPEG, PNG eller WebP. Om mobilen använder HEIC, exportera bilden som JPEG först.');if(file.size>30*1024*1024)throw Error('Välj en bild mindre än 30 MB.');let image;try{image=await createImageBitmap(file,{imageOrientation:'from-image'});}catch{throw Error('Bilden kunde inte öppnas. Välj en annan bild.');}try{const scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let blob;for(const quality of [.86,.7,.5]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<1500000)break;}if(!blob||blob.size>=1500000)throw Error('Bilden kunde inte anpassas. Välj en annan bild.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Bilden kunde inte läsas.'));reader.readAsDataURL(blob);});return {mime:'image/jpeg',data};}finally{image.close();}}
async function matchSearchView(){const params=new URLSearchParams(location.hash.split('?')[1]),q=params.get('q')||'',season=params.get('season')||user.season,offset=params.get('offset')||'0';let d=null;if(q.trim().length>=2)d=await api('/match-search?'+new URLSearchParams({q,season,offset}));return `<h2>Sök matcher och domare</h2><p>Förbered din nästa match. Sök på lag, serie eller domarnamn, även när ingen har lämnat en kommentar. Endast importerade matcher i VDK:s område visas.</p><form id="match-search-form" class="card"><div class="field"><label for="match-query">Lag, serie eller domare</label><input id="match-query" name="q" type="search" minlength="2" maxlength="150" required value="${esc(q)}" placeholder="Till exempel Skattkärr, Jonas Snäll eller HJ18"></div>${statisticsSelect('Säsong','season',[{id:'all',name:'Alla säsonger'},...statisticsSeasons.map(x=>({id:x,name:x}))],season,null,'search')}${formFooter('Sök matcher')}</form>${d?`<p role="status">${d.total} matcher hittades${d.total?' · visar '+(d.offset+1)+'–'+(d.offset+d.matches.length):''}.</p><div class="match-search-results">${d.matches.map(m=>`<article class="card"><h3>${esc(m.home)} – ${esc(m.away)}</h3><p>${date(m.starts_at)} · ${esc(m.season)}<br>${esc(m.competition_name)}</p><h4>Domare</h4>${m.referees.length?m.referees.map(r=>`<div class="search-referee"><span>${esc(r.name)}</span>${r.userId?`<div class="inline-actions"><a class="text-link" href="#/mina-sidor/medlemsprofil?id=${r.userId}">Profil</a>${r.userId!==user.id?`<a class="button button-outline button-small" href="#/mina-sidor/meddelanden?to=${r.userId}">Skriv meddelande</a>`:''}</div>`:'<small>Inget aktivt VDK-konto kopplat</small>'}</div>`).join(''):'<p>Domaruppgift saknas i protokollet.</p>'}<div class="inline-actions"><a class="text-link" href="#/mina-sidor/matchkommentar?id=${m.id}">${m.comment_count?m.comment_count+' kommentarer':'Inga kommentarer – öppna matchen'}</a><a class="text-link" href="${esc(m.source_url)}" target="_blank" rel="noopener">Matchprotokoll</a></div></article>`).join('')}</div><div class="inline-actions">${d.offset>0?`<a class="button button-outline" href="#/mina-sidor/sok-matcher?${esc(new URLSearchParams({q,season,offset:String(Math.max(0,d.offset-30))}))}">Föregående</a>`:''}${d.hasMore?`<a class="button" href="#/mina-sidor/sok-matcher?${esc(new URLSearchParams({q,season,offset:String(d.offset+30)}))}">Nästa 30 matcher</a>`:''}</div>`:'<p>Skriv ett sökord för att hitta matcher.</p>'}`;}
function bindProfilesAndSearch(){document.querySelector('#member-profile-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async data=>{data.share_profile=e.target.elements.share_profile.checked;data.share_photo=e.target.elements.share_photo.checked;await api('/profile',{method:'POST',body:data});toast('Din profil är sparad.');});});document.querySelector('#profile-photo-form')?.addEventListener('submit',e=>{e.preventDefault();submit(e.target,async()=>{const file=e.target.elements.photo.files[0];const body=await prepareProfilePhoto(file);await api('/profile/photo',{method:'POST',body});toast('Profilbilden är sparad.');await route();});});document.querySelector('#match-search-form')?.addEventListener('submit',async e=>{e.preventDefault();history.pushState(null,'','#/mina-sidor/sok-matcher?'+new URLSearchParams(new FormData(e.target)));await route();});}
